-- Spanish (Spain) localization for EllesmereUI. Community-maintained.
-- Encoding: UTF-8 without BOM. See CONTRIBUTING_TRANSLATIONS.md.
-- Seed locale: high-frequency common vocabulary. Run /euiloc dump esES in-game
-- to generate the full remaining key list. Untranslated keys fall back to English.

local L = EllesmereUI.RegisterLocale("esES")
if not L then return end

