-- == Batch 1: feature descriptions & preset blurbs ============================
L["A CDM replacement focused on performance, customizations and alerts."] = "Un reemplazo del Gestor de reutilización (CDM), centrado en el rendimiento, las personalizaciones y las alertas."
L["A Frame Strata dropdown in the Character Crosshair cog controls whether the crosshair draws above or below other UI"] = "Un menú desplegable de nivel de marco en el engranaje de la mira del personaje controla si la mira se dibuja por encima o por debajo del resto de la interfaz"
L["A Horizontally Growing Anchor Target"] = "Un objetivo de anclaje con crecimiento horizontal"
L["A UI reload is needed to add this icon to the sidebar."] = "Se necesita recargar la interfaz para añadir este icono a la barra lateral."
L["A UI reload is needed to apply the extended chat background."] = "Se necesita recargar la interfaz para aplicar el fondo extendido del chat."
L["A UI reload is needed to apply your sidebar icon changes."] = "Se necesita recargar la interfaz para aplicar los cambios de iconos de la barra lateral."
L["A Vertically Growing Anchor Target"] = "Un objetivo de anclaje con crecimiento vertical"
L["A beautiful visual refresh of Blizzard Bags with intuitive organization."] = "Una hermosa renovación visual de las bolsas de Blizzard con una organización intuitiva."
L["A blank bar to build from scratch."] = "Una barra en blanco para crear desde cero."
L["A bright, minimalist layout with a clean aesthetic. Crafted for any role with clear information and a calm but focused feel."] = "Un diseño luminoso y minimalista con una estética limpia. Creado para cualquier rol, con información clara y una sensación tranquila pero concentrada."
L["A checked Hide visibility condition now always hides its element in both match modes, and every condition has its own Show and Hide row, with new Out of Combat and Not Skyriding (Airborne) rows."] = "Una condición de visibilidad Ocultar marcada ahora siempre oculta su elemento en ambos modos de coincidencia, y cada condición tiene su propia fila de Mostrar y Ocultar, con nuevas filas de Fuera de combate y Sin planeo (en el aire)."
L["A clean minimal setup"] = "Una configuración limpia y minimalista"
L["A clean, airy layout with a calm feel and clear information at a glance. Comfortable for long sessions in any content."] = "Un diseño limpio y ligero con una sensación tranquila e información clara de un vistazo. Cómodo para sesiones largas en cualquier contenido."
L["A clean, updated reskin of Blizzard's Quest Tracker."] = "Un rediseño limpio y actualizado del seguimiento de misiones de Blizzard."
L["A dark, elegant healing setup built around raid frames and a clean display of information to help keep your team alive at a glance."] = "Una configuración de sanación oscura y elegante, construida en torno a los marcos de banda y una presentación limpia de la información para ayudarte a mantener vivo a tu equipo de un vistazo."
L["A luminous healing setup built around raid frames and crisp readability, keeping your team's health front and center at a glance."] = "Una configuración de sanación luminosa, construida en torno a los marcos de banda y una gran legibilidad, manteniendo la vida de tu equipo en primer plano de un vistazo."
L["A modern friends list with built-in organization tools."] = "Una lista de amigos moderna con herramientas de organización integradas."
L["A new Use Modifier option makes the spell and item ID lines on tooltips appear only while you hold Shift, Control, or Alt."] = "Una nueva opción de modificador de uso hace que las líneas de ID de hechizo y objeto en los tooltips solo aparezcan mientras mantienes pulsado Mayús, Ctrl o Alt."
L["A new age minimap with clean styling and square layout options."] = "Un minimapa de nueva era con un estilo limpio y opciones de diseño cuadrado."
L["A new built-in profile preset: the damage dealer cut of Midnight Lily, a focused low-clutter layout that keeps your rotation and cooldowns front and center."] = "Un nuevo perfil preestablecido integrado: la versión para daño de Midnight Lily, un diseño concentrado y ordenado que mantiene tu rotación y reutilizaciones en primer plano."
L["A new option that makes enemy nameplates pulse with a red glow the moment a target drops below 30% health, so a whole pack tells you at a glance which mobs are in execute range."] = "Una nueva opción hace que las placas de nombre enemigas pulsen con un resplandor rojo en el momento en que un objetivo cae por debajo del 30% de vida, para que una horda entera te indique de un vistazo qué enemigos están en rango de ejecución."
L["A profile named \"%1$s\" already exists. Please choose a different name."] = "Ya existe un perfil llamado \"%1$s\". Elige un nombre diferente."
L["A quick view of every font setting in one place."] = "Una vista rápida de todos los ajustes de fuente en un solo lugar."
L["A quick view of every texture setting in one place."] = "Una vista rápida de todos los ajustes de textura en un solo lugar."
L["A raid control panel with ready check, pull timer and raid markers. In a raid it only shows while you are the leader or an assistant, since none of its buttons work without that; in a party it always shows."] = "Un panel de control de banda con verificación de preparación, temporizador de pull y marcadores de banda. En una banda solo se muestra mientras eres el líder o un asistente, ya que ninguno de sus botones funciona sin eso; en un grupo siempre se muestra." -- JARGAO (pull)
L["A shadowed, understated layout that keeps the screen quiet and the essentials close. Information appears exactly when you need it."] = "Un diseño discreto y sombreado que mantiene la pantalla tranquila y lo esencial cerca. La información aparece exactamente cuando la necesitas."
L["A simple Mythic+ timer with full tracking customizations."] = "Un temporizador sencillo de Mítica+ con personalizaciones completas de seguimiento."
L["A spec override owns this setting, so this conditional value never applies outside an editing session. Remove the spec override to let it through."] = "Una anulación de especialización controla este ajuste, por lo que este valor condicional nunca se aplica fuera de una sesión de edición. Elimina la anulación de especialización para permitirlo."
L["A spec override setting Visibility to Never no longer leaves the frame missing after switching back to another spec."] = "Una anulación de especialización que establece Visibilidad en Nunca ya no deja el marco desaparecido al volver a otra especialización."

