L["Add diminishing-returns detail (adjusted rating, wasted rating, and current penalty bracket) to the Secondary and Tertiary stat tooltips."] = "Añade detalles de rendimientos decrecientes (valoración ajustada, valoración desperdiciada y el tramo de penalización actual) a los tooltips de estadísticas secundarias y terciarias."
