L["Adds Bonus Roll and Group Loot movers to Unlock Mode."] = "Añade movibles de tirada de bonificación y botín de grupo al modo de desbloqueo."
L["Adds Bonus Roll, Group Loot, and Alert Toast movers to Unlock Mode."] = "Añade movibles de tirada de bonificación, botín de grupo y notificaciones emergentes al modo de desbloqueo."
L["Adds a 'Train All' button next to the Train button at profession trainers, allowing you to learn all available skills with one click."] = "Añade un botón 'Aprender todo' junto al botón Aprender en los entrenadores de profesión, permitiéndote aprender todas las habilidades disponibles con un clic."
L["Adds a Calc toggle button to the character sheet that opens and closes the Upgrade Calculator."] = "Añade un botón de calculadora a la ficha de personaje que abre y cierra la Calculadora de mejora."
L["Adds a Shadow border to your player frame when you pull or hold threat as a non-tank. Only active in dungeons, raids and delves."] = "Añade un borde oscuro a tu marco de jugador cuando generas o mantienes amenaza sin ser tanque. Solo activo en mazmorras, bandas y galerías." -- TODO: confirmar termo oficial (Delves)
L["Adds a Targeting line showing who the hovered player or NPC is targeting, in green when it's you."] = "Añade una línea de objetivo que muestra a quién está apuntando el jugador o PNJ señalado, en verde cuando eres tú."
L["Adds a compact Raid Tools window -- target/world markers, ready check, role check and pull timer in one resizable row. It runs alongside whichever Show as layout is picked above (or with Raid Tools fully off), moves and resizes independently through Unlock Mode, and only appears while you're actually in a raid group."] = "Añade una ventana compacta de herramientas de banda: marcadores de objetivo/mundo, verificación de preparación, verificación de rol y temporizador de pull en una sola fila redimensionable. Funciona junto con el diseño de Mostrar como que elijas arriba (o con las herramientas de banda totalmente desactivadas), se mueve y redimensiona de forma independiente a través del modo de desbloqueo, y solo aparece mientras estás realmente en un grupo de banda." -- JARGAO (pull)
L["Adds a mover for Blizzard's top-center event text and widgets (scenario, event, and encounter bars)."] = "Añade un movible para el texto de eventos y los widgets superiores centrales de Blizzard (barras de escenario, evento y encuentro)."
L["Adds a small filled dot at the center of the cursor circle. Uses the same color and opacity as the circle."] = "Añade un punto relleno pequeño en el centro del círculo del cursor. Usa el mismo color y opacidad que el círculo."
L["Adds a steady red glow around the nameplate while the Near Aggro color is active."] = "Añade un resplandor rojo constante alrededor de la placa de nombre mientras el color de Aggro cercano está activo." -- JARGAO (Aggro)
L["Adds a strip down the left edge of a loot toast in the item's quality color. The flat skin drops Blizzard's quality ring around the icon, so this puts that rarity cue back."] = "Añade una franja en el borde izquierdo de la notificación de botín con el color de calidad del objeto. El estilo plano elimina el anillo de calidad de Blizzard alrededor del icono, así que esto recupera esa indicación de rareza."
L["Adds the mount a player is riding to their tooltip, with a green check if you own it or a red X if you don't."] = "Añade la montura que un jugador está usando a su tooltip, con una marca verde si la tienes o una X roja si no."
L["Adds three optional world-marker keybinds that remain usable in combat. Place drops the first free marker at the cursor in Star to Skull order; Undo removes the last marker placed through Quick Fire; Clear removes all world markers. Every binding starts empty. Marker changes made elsewhere during combat are picked up afterward."] = "Añade tres atajos de teclado opcionales para marcadores de mundo que siguen siendo utilizables en combate. Colocar suelta el primer marcador libre en el cursor en el orden de Estrella a Calavera; Deshacer elimina el último marcador colocado mediante disparo rápido; Borrar elimina todos los marcadores de mundo. Cada atajo empieza vacío. Los cambios de marcadores hechos en otro lugar durante el combate se recogen después."
L["Adds timestamps to system messages, loot, achievements, and addon messages, not just player chat."] = "Añade marcas de tiempo a los mensajes de sistema, botín, logros y mensajes de complementos, no solo al chat de jugadores."
L["AdiBags"] = true
