L["Automatic follows the zone name. Manual holds the block at a fixed width and clips longer names, so it never shifts the blocks beside it."] = "Automático sigue el nombre de la zona. Manual mantiene el bloque en un ancho fijo y recorta los nombres más largos, para que nunca desplace los bloques de al lado."
L["Automatic shows XP while leveling and reputation at max level."] = "Automático muestra la experiencia mientras subes de nivel y la reputación al nivel máximo."
L["Automatic"] = "Automático"
L["Automatically Skip If Possible"] = "Omitir automáticamente si es posible"
L["Automatically add a bar to this group for every spell in Blizzard's Tracked Bars section, now and whenever a new one appears."] = "Añade automáticamente una barra a este grupo por cada hechizo en la sección de barras de seguimiento de Blizzard, ahora y cada vez que aparezca una nueva."
L["Automatically dismisses the 'new mount/pet/toy' fanfare notification when you receive one, so you don't have to click through the collections journal."] = "Descarta automáticamente la notificación de fanfarria de 'nueva montura/mascota/juguete' cuando recibes una, para que no tengas que pasar por el diario de colecciones."
L["Automatically duplicates the raid's tanks into the Extra Frames group. Shares the 5-frame cap with hotkey picks."] = "Duplica automáticamente los tanques de la banda en el grupo de marcos adicionales. Comparte el límite de 5 marcos con las selecciones por tecla rápida."
L["Automatically duplicates the raid's tanks into the Extra Frames group. Shares the frame cap with hotkey picks."] = "Duplica automáticamente los tanques de la banda en el grupo de marcos adicionales. Comparte el límite de marcos con las selecciones por tecla rápida."
L["Automatically enables the 'Current Expansion Only' filter whenever you open the Auction House."] = "Activa automáticamente el filtro 'Solo expansión actual' cada vez que abres la casa de subastas."
L["Automatically hides unused action slots and resizes the bar to fit its assigned actions. Empty slots return while dragging an action so you can place it anywhere."] = "Oculta automáticamente las ranuras de acción no usadas y redimensiona la barra para ajustarse a sus acciones asignadas. Las ranuras vacías reaparecen mientras arrastras una acción para que puedas colocarla donde quieras."
L["Automatically inserts your key into the Font of Power."] = "Inserta automáticamente tu llave en la Fuente de poder."
L["Automatically opens and closes the Upgrade Calculator when the Character Sheet is opened or closed."] = "Abre y cierra automáticamente la Calculadora de mejora cuando se abre o cierra la ficha de personaje."
L["Automatically opens bags, boxes and parcels in your inventory when they are added to your bags.\n\nContainers received from the mailbox are held until you close the mailbox, so opening them cannot collide with mail still delivering items."] = "Abre automáticamente bolsas, cajas y paquetes en tu inventario cuando se añaden a tus bolsas.\n\nLos contenedores recibidos del buzón se retienen hasta que cierras el buzón, para que abrirlos no interfiera con el correo que aún está entregando objetos."
L["Automatically opens the Upgrade Calculator when the Crest Upgrade NPC window is opened."] = "Abre automáticamente la Calculadora de mejora cuando se abre la ventana del PNJ de mejora de crestas."
L["Automatically refreshes the Premade Groups list every few seconds while you are browsing, so newly posted groups appear without clicking Refresh."] = "Actualiza automáticamente la lista de grupos preformados cada pocos segundos mientras la consultas, para que los grupos publicados recientemente aparezcan sin pulsar Actualizar."
L["Automatically removes cosmetic transforms when they are applied to you, such as profession gear, holiday costumes, toys and consumables. Use the cog to pick exactly which transforms are removed. Transforms applied during combat are removed when combat ends."] = "Elimina automáticamente las transformaciones cosméticas cuando se te aplican, como el equipo de profesión, los disfraces festivos, los juguetes y los consumibles. Usa el engranaje para elegir exactamente qué transformaciones se eliminan. Las transformaciones aplicadas durante el combate se eliminan al terminar el combate."
L["Automatically repair all gear when visiting a repair vendor."] = "Repara automáticamente todo el equipo al visitar un vendedor de reparaciones."
L["Automatically sell all junk items when visiting a vendor."] = "Vende automáticamente todos los objetos de chatarra al visitar un vendedor."
L["Automatically starts and stops combat logging when entering or leaving a loggable instance."] = "Inicia y detiene automáticamente el registro de combate al entrar o salir de una instancia registrable."
L["Automatically types DELETE when throwing away a valuable item. Also allows you to press enter to accept the deletion."] = "Escribe automáticamente ELIMINAR al descartar un objeto valioso. También te permite pulsar Intro para aceptar la eliminación."
L["Automatically zoom back out to maximum distance after this many seconds of no manual zoom change. 0 disables the reset."] = "Aleja automáticamente la cámara a la distancia máxima tras esta cantidad de segundos sin cambio manual de zoom. 0 desactiva el restablecimiento."
L["Available only when Anchor to Windows is set to Free Move."] = "Disponible solo cuando Anclar a ventanas está configurado en Movimiento libre."
