L["Choose which addons to include in your exported profile. Check everything for a full profile export."] = "Elige qué complementos incluir en tu perfil exportado. Marca todo para una exportación completa del perfil."
L["Choose which addons you want enabled. You can change any of these later in the EllesmereUI settings panel."] = "Elige qué complementos quieres activar. Puedes cambiar cualquiera de ellos más tarde en el panel de ajustes de EllesmereUI."
L["Choose which channels get a bubble.\n\nSay, Yell, NPCs and Emotes share one Blizzard switch. It is turned on while at least one of the four is ticked, and put back the way you had it once you clear the last one. Party and Raid have switches of their own and start out matching what you already had, so no group bubbles turn up in a chat that had none.\n\nGuild is not offered: Blizzard draws no bubble for guild chat, and there is nothing for us to restyle."] = "Elige qué canales reciben un globo.\n\nDecir, Gritar, PNJ y Emotes comparten un único interruptor de Blizzard. Se activa mientras al menos uno de los cuatro esté marcado, y vuelve a como estaba en cuanto desmarcas el último. Grupo y Banda tienen sus propios interruptores y empiezan igual que ya los tenías, así que no aparecen globos de grupo en un chat que no tenía ninguno.\n\nHermandad no se ofrece: Blizzard no dibuja ningún globo para el chat de hermandad, y no hay nada que podamos reestilizar."
L["Choose which nameplates stack vertically instead of overlapping."] = "Elige qué placas de nombre se apilan verticalmente en lugar de superponerse."
