L["Closes an open menu without using anything. Escape always does this as well. One key shared by every menu, claimed only while a menu is up -- a mouse button keeps its normal use the rest of the time."] = "Cierra un menú abierto sin usar nada. Escape también hace esto siempre. Una tecla compartida por todos los menús, reclamada solo mientras hay un menú abierto; un botón del ratón mantiene su uso normal el resto del tiempo."
L["Closes an open menu without using anything. Escape always does this as well. One key shared by every menu, claimed only while a menu is up -- a mouse button keeps its normal use the rest of the time.\n\nLeft-click to set a keybind, then press any key or\nclick any mouse button to use it.\nEscape cancels. Right-click here to unbind."] = "Cierra un menú abierto sin usar nada. Escape también hace esto siempre. Una tecla compartida por todos los menús, reclamada solo mientras hay un menú abierto; un botón del ratón mantiene su uso normal el resto del tiempo.\n\nHaz clic izquierdo para asignar una tecla, luego pulsa cualquier tecla o\nhaz clic en cualquier botón del ratón para usarla.\nEscape cancela. Haz clic derecho aquí para desasignar."
L["Cobra Shot"] = "Disparo de cobra" -- TODO: confirmar termo oficial
