L["Collapse subgroups that have no members so the remaining groups close ranks. For example, if only groups 1, 2, 3 and 6 have players, they show with no gaps instead of leaving empty space where groups 4 and 5 would be. Real raid frames only."] = "Contrae los subgrupos sin miembros para que los grupos restantes cierren filas. Por ejemplo, si solo los grupos 1, 2, 3 y 6 tienen jugadores, se muestran sin huecos en lugar de dejar espacio vacío donde estarían los grupos 4 y 5. Solo marcos de banda reales."
L["Collapses the windows back to the icon on their own after they've been open (and the cursor hasn't been over them) for the delay below -- the same result as clicking the close button, just on a timer. Moving the cursor over the windows pauses the timer and it starts over once you look away."] = "Las ventanas se contraen de nuevo al icono por sí solas tras haber estado abiertas (y sin que el cursor haya estado sobre ellas) durante el retraso indicado abajo; el mismo resultado que hacer clic en el botón de cerrar, pero con un temporizador. Mover el cursor sobre las ventanas pausa el temporizador, que se reinicia en cuanto apartas la vista."
