L["Color of the flat overlay behind the Compact Band's buttons."] = "Color de la superposición plana detrás de los botones de la Banda compacta."
L["Color of the out-of-range darken overlay. Defaults to gray -- pick something else if it's hard to see against your Fill Color."] = "Color de la superposición oscura de fuera de alcance. Por defecto es gris; elige otro color si es difícil de ver contra tu Color de relleno."
L["Color the bar by ranges instead of a single threshold.\nUp to (<=) / From (>=)\nAny remaning values outside the bands will use fill color.\n|cff888888Bars can use % or actual value; pip resources use counts.|r"] = "Colorea la barra por rangos en lugar de un único umbral.\nHasta (<=) / Desde (>=)\nCualquier valor restante fuera de las bandas usará el color de relleno.\n|cff888888Las barras pueden usar % o el valor real; los recursos de indicadores usan cantidades.|r"
L["Color the bar differently at several stack counts. The highest count you have reached wins."] = "Colorea la barra de forma diferente en varios recuentos de pilas. Gana el recuento más alto que hayas alcanzado."
L["Color the health bar by how much health is left, instead of a flat color. Classic runs green at full health through yellow to red at empty. Custom Colors blends between the three stop swatches on this row -- full (100%), half (50%) and empty (0%). Class Reactive shows the class color at full health, bleeding into the 50% and 0% colors as the unit takes damage. Off leaves the flat Fill Color swatches in charge; either way the Gradient below still applies, running from whichever color this picks."] = "Colorea la barra de vida según la vida restante, en lugar de un color plano. Clásico va de verde a plena vida, pasando por amarillo, hasta rojo al vaciarse. Colores personalizados mezcla entre las tres muestras de esta fila: llena (100%), mitad (50%) y vacía (0%). Reactivo a la clase muestra el color de clase a plena vida, difuminándose hacia los colores del 50% y el 0% a medida que la unidad recibe daño. Desactivado deja las muestras planas de Color de relleno al mando; de cualquier forma, el Degradado de abajo sigue aplicándose, partiendo del color que elijas aquí."
