L["EllesmereUI Addon Split"] = "División de complementos de EllesmereUI"
L["EllesmereUI Background"] = "Fondo de EllesmereUI"
L["EllesmereUI Basics has been split into separate addons. Since you had Basics disabled, Minimap, Friends, and Quest Tracker have been disabled to match. A reload is required to apply this change."] = "EllesmereUI Basics se ha dividido en complementos independientes. Como tenías Basics desactivado, Minimapa, Amigos y Seguimiento de misiones se han desactivado para coincidir. Se requiere una recarga para aplicar este cambio."
L["EllesmereUI Beta Complete"] = "Beta de EllesmereUI completada"
L["EllesmereUI Default"] = "Predeterminado de EllesmereUI"
