L["EllesmereUI Profile switched. Reload UI to apply?"] = "Se cambió el perfil de EllesmereUI. ¿Recargar la interfaz para aplicarlo?"
L["EllesmereUI Raid Frames are here! Clean, fully customizable, and built for performance."] = "¡Ya están aquí los Marcos de banda de EllesmereUI! Limpios, totalmente personalizables y creados para el rendimiento."
L["EllesmereUI WonderBar"] = true
L["EllesmereUI WonderBar was renamed to EllesmereUI DataBars. The old WonderBar addon is still installed and both create the same bar. Please disable or delete the EllesmereUIWonderBar addon."] = "EllesmereUI WonderBar pasó a llamarse EllesmereUI DataBars. El complemento antiguo WonderBar sigue instalado y ambos crean la misma barra. Desactiva o elimina el complemento EllesmereUIWonderBar."
L["EllesmereUI could not save this change to your Edit Mode layout, so it has to be set by hand. The Cooldown Manager has to be off while you do it, because it hides Blizzard's cooldown viewers and a hidden viewer cannot be selected in Edit Mode.\n\n"] = "EllesmereUI no pudo guardar este cambio en tu diseño del Modo de edición, así que hay que definirlo a mano. El Gestor de tiempos de reutilización debe estar desactivado mientras lo haces, porque oculta los visores de tiempos de reutilización de Blizzard y un visor oculto no se puede seleccionar en el Modo de edición.\n\n"
L["EllesmereUI could not save this change to your Edit Mode layout, so it has to be set by hand. The Cooldown Manager has to be off while you do it, because it hides Blizzard's cooldown viewers and a hidden viewer cannot be selected in Edit Mode.\n\n1. Disable EllesmereUI Cooldown Manager (button below).\n2. Open Edit Mode from the Game Menu.\n3. Select each Cooldown Manager viewer and set Visibility to Always.\n4. On Tracked Buffs and Tracked Bars, tick Hide When Inactive.\n5. Save the layout and leave Edit Mode.\n6. Re-enable EllesmereUI Cooldown Manager."] = "EllesmereUI no pudo guardar este cambio en tu diseño del Modo de edición, así que hay que definirlo a mano. El Gestor de tiempos de reutilización debe estar desactivado mientras lo haces, porque oculta los visores de tiempos de reutilización de Blizzard y un visor oculto no se puede seleccionar en el Modo de edición.\n\n1. Desactiva el Gestor de tiempos de reutilización de EllesmereUI (botón de abajo).\n2. Abre el Modo de edición desde el Menú de juego.\n3. Selecciona cada visor del Gestor de tiempos de reutilización y define Visibilidad en Siempre.\n4. En Beneficios seguidos y Barras seguidas, marca Ocultar cuando esté inactivo.\n5. Guarda el diseño y sal del Modo de edición.\n6. Vuelve a activar el Gestor de tiempos de reutilización de EllesmereUI."
L["EllesmereUI has updated your CDM Edit Mode settings to ensure cooldown tracking works correctly.\n\nA UI reload is required for the changes to take effect."] = "EllesmereUI ha actualizado tus ajustes del Modo de edición del CDM para garantizar que el seguimiento de tiempos de reutilización funcione correctamente.\n\nSe requiere una recarga de la interfaz para que los cambios surtan efecto."
L["EllesmereUI matches the window-skin shell; Modern is a flat color."] = "EllesmereUI coincide con la carcasa del skin de ventana; Moderno es un color plano."
L["EllesmereUI restyles Blizzard's chat bubbles and turns on the switches it needs. Party and Raid keep your current setting, and everything is put back when you turn this off."] = "EllesmereUI reestiliza los globos de chat de Blizzard y activa los interruptores que necesita. Grupo y Banda mantienen tu ajuste actual, y todo se restaura cuando desactivas esto."
L["ElvUI"] = true
L["Elyndra"] = true
L["Embertide"] = true

