L["Hide and show every damage meter window at once. The state is not saved; a reload restores the configured visibility.\n\nThe bound key is taken over while it is set. Use the cog to include the combat timer and Spell History.\n\nLeft-click to set a keybind.\nRight-click to unbind."] = "Oculta y muestra todas las ventanas del medidor de daño a la vez. El estado no se guarda; una recarga restaura la visibilidad configurada.\n\nLa tecla asignada queda reservada mientras esté definida. Usa el engranaje para incluir el temporizador de combate y el Historial de hechizos.\n\nClic izquierdo para definir un atajo de teclado.\nClic derecho para desvincular."
L["Hide combat indicator preview"] = "Ocultar vista previa del indicador de combate"
L["Hide consumable items (potions, healthstone) from the bar when you have none in your bags, instead of showing them dimmed. They reappear automatically once you have the item again."] = "Oculta los objetos consumibles (pociones, piedra de salud) de la barra cuando no tienes ninguno en las bolsas, en lugar de mostrarlos atenuados. Reaparecen automáticamente en cuanto vuelves a tener el objeto."
L["Hide crafted items from the gear tile list.\nCrafted items cannot be upgraded at the Upgrade NPC."] = "Oculta los objetos fabricados de la lista de mosaicos de equipo.\nLos objetos fabricados no se pueden mejorar en el PNJ de mejora."
L["Hide debuffs on preview"] = "Ocultar perjuicios en la vista previa"
L["Hide defensives on preview"] = "Ocultar defensivas en la vista previa"
L["Hide dispel overlay preview"] = "Ocultar vista previa de superposición de disipación"
L["Hide dispels on preview"] = "Ocultar disipaciones en la vista previa"
L["Hide enemy nameplates while you are out of combat; they return the moment combat starts. Drives the same game setting as the Show Enemy Name Plates keybind."] = "Oculta las placas de nombre enemigas mientras estás fuera de combate; vuelven en cuanto empieza el combate. Controla el mismo ajuste del juego que el atajo de teclado Mostrar placas de nombre enemigas."
L["Hide entries this character cannot use: another class's specializations and spells, and macros this character does not have. One shared menu then fits every character. The menu editor always shows every entry."] = "Oculta las entradas que este personaje no puede usar: especializaciones y hechizos de otra clase, y macros que este personaje no tiene. Así un único menú compartido sirve para todos los personajes. El editor de menús siempre muestra todas las entradas."
L["Hide every Cooldown Manager glow out of combat and bring them all back the moment you enter combat."] = "Oculta todos los resplandores del Gestor de tiempos de reutilización fuera de combate y los devuelve en cuanto entras en combate."
L["Hide every Cooldown Manager glow while you are out of combat: proc glows, active state, max stacks, buff and pandemic glows, cooldown ready glows and bar glows.\n\nThey come back the moment you enter combat, including a glow that started before the pull.\n\nApplies to every CDM bar and to the Tracking Bars at once. Glows from other EllesmereUI modules are not affected.\n\nThe Bar Glows page keeps its own per-mapping Only In Combat toggle; this one applies on top of it."] = "Oculta todos los resplandores del Gestor de tiempos de reutilización mientras estás fuera de combate: resplandores de proc, estado activo, pilas máximas, resplandores de beneficio y pandemia, resplandores de reutilización lista y resplandores de barra.\n\nVuelven en cuanto entras en combate, incluido un resplandor que empezó antes del pull.\n\nSe aplica a todas las barras del CDM y a las Barras de seguimiento a la vez. Los resplandores de otros módulos de EllesmereUI no se ven afectados.\n\nLa página de Resplandores de barra mantiene su propio interruptor de Solo en combate por asignación; este se aplica encima de ese."
L["Hide friendly player health bars and instead only see their names.\n\nRequires 'Simplified Friendly Nameplates' to be disabled in Blizzard's Nameplate settings (Esc > Options > Nameplates)."] = "Oculta las barras de salud de jugadores amistosos y en su lugar solo muestra sus nombres.\n\nRequiere que 'Placas de nombre amistosas simplificadas' esté desactivado en los ajustes de placas de nombre de Blizzard (Esc > Opciones > Placas de nombre)."
L["Hide heal absorb preview"] = "Ocultar vista previa de absorción de curación"
