L["Hide private auras on preview"] = "Ocultar auras privadas en la vista previa"
L["Hide role icons while you are in combat."] = "Oculta los iconos de rol mientras estás en combate."
L["Hide shield effects on preview"] = "Ocultar efectos de escudo en la vista previa"
L["Hide sidebar categories that have no items in them."] = "Oculta las categorías de la barra lateral que no tienen objetos."
L["Hide targeted spells on preview"] = "Ocultar hechizos dirigidos en la vista previa"
L["Hide the 1-pixel border around the cast bar spell icon."] = "Oculta el borde de 1 píxel alrededor del icono de hechizo de la barra de lanzamiento."
L["Hide the 1-pixel outline around the bar."] = "Oculta el contorno de 1 píxel alrededor de la barra."
L["Hide the Reset Data button from the damage meter header."] = "Oculta el botón Restablecer datos del encabezado del medidor de daño."
L["Hide the brief GCD swipe that flashes when you cast any spell. The actual ability cooldown swipe still shows."] = "Oculta el breve barrido del TGC que destella al lanzar cualquier hechizo. El barrido de reutilización real de la habilidad se sigue mostrando."
L["Hide the charge number on action buttons when it reaches 0, instead of showing a 0. The number returns as soon as a charge or item comes back."] = "Oculta el número de cargas en los botones de acción cuando llega a 0, en lugar de mostrar un 0. El número vuelve en cuanto se recupera una carga u objeto."
L["Hide the charge number while a spell has no charges left, instead of showing a 0. The number returns as soon as a charge comes back."] = "Oculta el número de cargas mientras un hechizo no tiene cargas restantes, en lugar de mostrar un 0. El número vuelve en cuanto se recupera una carga."
L["Hide the enemy name text while that nameplate's cast bar is visible."] = "Oculta el texto del nombre del enemigo mientras la barra de lanzamiento de esa placa de nombre es visible."
L["Hide the icon texture, border, and duration swipe, leaving only the stack count. Forces icon opacity, border, and duration swipe off."] = "Oculta la textura, el borde y el barrido de duración del icono, dejando solo el recuento de pilas. Fuerza la desactivación de la opacidad, el borde y el barrido de duración del icono."
L["Hide the preview"] = "Ocultar la vista previa"
L["Hide the randomize (dice) button in the OneBag view."] = "Oculta el botón de aleatorizar (dado) en la vista de OneBag."
L["Hide the tooltip when hovering a buff/HoT icon on a raid or party frame."] = "Oculta el tooltip al pasar el ratón sobre un icono de beneficio/HoT en un marco de banda o grupo."
L["Hide the warning text at the top of the OneBag and MultiBag views."] = "Oculta el texto de advertencia en la parte superior de las vistas de OneBag y MultiBag."
L["Hide the warning text at the top of the OneBag view."] = "Oculta el texto de advertencia en la parte superior de la vista de OneBag."
L["Hide these instead of showing them"] = "Ocultar estos en lugar de mostrarlos"
L["Hide this bar completely while out of combat, even when the tracked buff/cooldown is active."] = "Oculta esta barra completamente mientras está fuera de combate, incluso cuando el beneficio/tiempo de reutilización seguido está activo."
L["Hide this bar's icon art, cooldown swipe, recharge edge and cooldown text, leaving only the charge or stack count."] = "Oculta el arte del icono, el barrido de reutilización, el borde de recarga y el texto de reutilización de esta barra, dejando solo el recuento de cargas o pilas."
L["Hide this bar's icons and show only the duration text."] = "Oculta los iconos de esta barra y muestra solo el texto de duración."
L["Hide when Dragonriding"] = "Ocultar durante el vuelo de dragones"
L["Hide when Mounted"] = "Ocultar cuando esté montado"
L["Hide when Skyriding Mounted"] = "Ocultar cuando esté montado en vuelo aéreo"
L["Hide while this condition is true"] = "Ocultar mientras esta condición sea verdadera"
L["Hide without Enemy Target"] = "Ocultar sin objetivo enemigo"
L["Hide without Target"] = "Ocultar sin objetivo"
L["Hides Blizzard's \"Loot Rolls\" window -- the running list of dropped items showing who rolled what and who won. Use the cog to let it appear briefly and close itself instead. The Need/Greed roll popups themselves are not affected."] = "Oculta la ventana de \"Tiradas de botín\" de Blizzard: la lista en curso de objetos caídos que muestra quién tiró qué y quién ganó. Usa el engranaje para que aparezca brevemente y se cierre sola en su lugar. Las ventanas emergentes de tirada de Necesidad/Codicia en sí no se ven afectadas."
L["Hides Blizzard's own micro menu while any bar has this on."] = "Oculta el micromenú propio de Blizzard mientras cualquier barra tenga esto activado."
L["Hides Blizzard's tutorial UI: the yellow HelpTip bubbles and the glowing (i) help-plate buttons on the spellbook, talents, map, collections, and other panels."] = "Oculta la interfaz de tutorial de Blizzard: los globos amarillos de ayuda y los botones brillantes (i) de ayuda en el libro de hechizos, talentos, mapa, colecciones y otros paneles."
L["Hides Pinned Items. Re-show in settings."] = "Oculta los objetos fijados. Vuelve a mostrarlos en los ajustes."
L["Hides Recent Items. Re-show in settings."] = "Oculta los objetos recientes. Vuelve a mostrarlos en los ajustes."
L["Hides most red error messages (such as 'Not enough rage' or 'Ability is not ready yet'). Important errors like a full bag or quest log are still shown."] = "Oculta la mayoría de los mensajes de error rojos (como 'No hay suficiente ira' o 'La habilidad aún no está lista'). Los errores importantes, como una bolsa llena o el registro de misiones, se siguen mostrando."
L["Hides the 'Screenshot saved' notification that appears on screen after taking a screenshot."] = "Oculta la notificación de 'Captura de pantalla guardada' que aparece en pantalla tras hacer una captura."
L["Hides the Add Category button at the bottom of the bag sidebar."] = "Oculta el botón Añadir categoría en la parte inferior de la barra lateral de bolsas."
L["Hides the EllesmereUI button from the game's Escape/pause menu."] = "Oculta el botón de EllesmereUI del menú de Escape/pausa del juego."
L["Hides the Lua error popup. The same setting as Global Settings > Developer."] = "Oculta la ventana emergente de error de Lua. El mismo ajuste que Ajustes globales > Desarrollador."
L["Hides the Top Bar Event Text mover in Unlock Mode while keeping its saved position applied."] = "Oculta el movible de Texto de evento de la barra superior en el modo de desbloqueo, manteniendo aplicada su posición guardada."
L["Hides the Unlock Mode button from the game's Escape/pause menu. You can still toggle Unlock Mode from the EUI options panel."] = "Oculta el botón del modo de desbloqueo del menú de Escape/pausa del juego. Aún puedes alternar el modo de desbloqueo desde el panel de opciones de EUI."
L["Hides the collapsed Blizzard party/raid sidebar panel on the side of the screen."] = "Oculta el panel lateral contraído de grupo/banda de Blizzard a un lado de la pantalla."
L["Hides the health bar Blizzard shows at the bottom of unit tooltips."] = "Oculta la barra de salud que Blizzard muestra en la parte inferior de los tooltips de unidad."
L["Hides the large NPC dialogue popup that appears during quests and dungeons."] = "Oculta la gran ventana emergente de diálogo de PNJ que aparece durante misiones y mazmorras."
L["Hides the loot window movers in Unlock Mode while keeping their saved positions applied."] = "Oculta los movibles de la ventana de botín en el modo de desbloqueo, manteniendo aplicadas sus posiciones guardadas."
L["Hides the master header and its minimize button at the top of the tracker. When shown, it's skinned to match the section headers below it (Quests, Achievements, ...)."] = "Oculta el encabezado maestro y su botón de minimizar en la parte superior del seguimiento. Cuando se muestra, se estiliza para coincidir con los encabezados de sección de debajo (Misiones, Logros, ...)."
L["Hides the rank number (1. 2. 3.) before each player name."] = "Oculta el número de rango (1. 2. 3.) antes del nombre de cada jugador."
L["Hides the ready check glyph above the prompt, leaving just the question and the Yes / No buttons. Applies while the Ready Check reskin is enabled."] = "Oculta el glifo de comprobación de preparación encima del aviso, dejando solo la pregunta y los botones Sí / No. Se aplica mientras el reskin de Comprobación de preparación está activado."
L["Hides the resize handle on the main chat frame, preventing accidental resizing."] = "Oculta el tirador de cambio de tamaño del marco de chat principal, evitando cambios de tamaño accidentales."
L["Hides the sync icons on the sidebar module list."] = "Oculta los iconos de sincronización en la lista de módulos de la barra lateral."
L["Hides this element while you are on a skyriding (glide-capable) mount, where Blizzard shows its vigor HUD."] = "Oculta este elemento mientras estás en una montura de vuelo aéreo (con capacidad de planeo), donde Blizzard muestra su HUD de vigor."
