L["Highlight Type"] = "Tipo de resaltado"
L["Highlights the final damage tick. Requires a supported channeled spell."] = "Resalta el último tic de daño. Requiere un hechizo canalizado compatible."
L["Hitbox Size X"] = "Tamaño de hitbox X" -- JARGAO (Hitbox = zona de colisión, término usado sin traducir por la comunidad)
L["Hitbox Size Y"] = "Tamaño de hitbox Y" -- JARGAO (Hitbox = zona de colisión, término usado sin traducir por la comunidad)
L["Hold Capped Artisan Payouts"] = "Retener pagos de artesano al límite"
L["Hold Shift to Skip"] = "Mantén pulsado Mayús para omitir"
L["Hold Shift+Click to Freely Move Icons"] = "Mantén pulsado Mayús+clic para mover iconos libremente"
L["Hold Shift+Click to Freely Move Standalone Timer"] = "Mantén pulsado Mayús+clic para mover libremente el temporizador independiente"
L["Hold a key to open a menu of actions; point or scroll to choose, release to fire."] = "Mantén pulsada una tecla para abrir un menú de acciones; apunta o desplázate para elegir, suelta para activar."
L["Hold a keybind to open a menu of actions; point or scroll to choose, release to fire."] = "Mantén pulsado un atajo de teclado para abrir un menú de acciones; apunta o desplázate para elegir, suelta para activar."
L["Hold a keybind to open a menu of actions; point or scroll to choose, release to fire. Build up to 16 menus in Arc, Fan, or Grid layouts, nest menus inside menus, and tune every setting per menu."] = "Mantén pulsado un atajo de teclado para abrir un menú de acciones; apunta o desplázate para elegir, suelta para activar. Crea hasta 16 menús en diseños de Arco, Abanico o Cuadrícula, anida menús dentro de menús y ajusta cada opción por menú."
L["Hold a keybind to open a palette of actions; point or scroll to choose, release to fire."] = "Mantén pulsado un atajo de teclado para abrir una paleta de acciones; apunta o desplázate para elegir, suelta para activar."
L["Holds the block at this width and clips longer text, so a plugin whose text keeps changing length never shifts the blocks beside it. Zero sizes the block to whatever the plugin currently says."] = "Mantiene el bloque en esta anchura y recorta el texto más largo, para que un plugin cuyo texto cambia de longitud nunca desplace los bloques de al lado. Cero ajusta el tamaño del bloque a lo que el plugin diga en cada momento."
