L["HoverCast"] = true
L["Hovercast is not available for unmodified left/right click"] = "Hovercast no está disponible para clic izquierdo/derecho sin modificar"
L["Hovering names in the Guild & Communities roster no longer errors, and member tooltips keep their race and class lines."] = "Pasar el ratón sobre los nombres en el listado de Hermandad y Comunidades ya no da error, y los tooltips de los miembros mantienen sus líneas de raza y clase."
L["How Blizzard's next-spell suggestion is drawn on the button. Button Overlay replaces the blue ring with a flat tint, leaving the button edge free for the proc glow."] = "Cómo se dibuja en el botón la sugerencia del siguiente hechizo de Blizzard. Superposición de botón sustituye el anillo azul por un tinte plano, dejando el borde del botón libre para el resplandor de proc."
L["How extra columns grow when the second column appears or disappears. Grow Right keeps the left column in place, Grow Left keeps the right column in place, Grow Centered keeps the bar centered."] = "Cómo crecen las columnas adicionales cuando aparece o desaparece la segunda columna. Crecer hacia la derecha mantiene la columna izquierda en su sitio, Crecer hacia la izquierda mantiene la columna derecha en su sitio, Crecer centrado mantiene la barra centrada."
L["How extra rows grow when the second row appears or disappears. Grow Down keeps the top row in place, Grow Up keeps the bottom row in place, Grow Centered keeps the bar centered."] = "Cómo crecen las filas adicionales cuando aparece o desaparece la segunda fila. Crecer hacia abajo mantiene la fila superior en su sitio, Crecer hacia arriba mantiene la fila inferior en su sitio, Crecer centrado mantiene la barra centrada."
L["How far along the arc a nest may spread its entries."] = "Hasta dónde a lo largo del arco puede extender un anidado sus entradas."
L["How far along the arc a nest may spread its entries. Contained keeps it clear of the next nest either side, so two of them are never drawn on top of one another. Overflowing lets it use the whole of Max Nest Span."] = "Hasta dónde a lo largo del arco puede extender un anidado sus entradas. Contenido lo mantiene alejado del siguiente anidado a cada lado, de modo que nunca se dibujan dos uno encima del otro. Desbordante le permite usar todo el Alcance máximo de anidado."
L["How far along the arc a nest may spread its entries. Contained keeps it clear of the next nest either side, so two of them are never drawn on top of one another. Overflowing lets it use the whole of Max Nest Span. A nest reaches over the plain entries it passes, and they only give up their angles while it is open."] = "Hasta dónde a lo largo del arco puede extender un anidado sus entradas. Contenido lo mantiene alejado del siguiente anidado a cada lado, de modo que nunca se dibujan dos uno encima del otro. Desbordante le permite usar todo el Alcance máximo de anidado. Un anidado se extiende sobre las entradas simples que atraviesa, y estas solo ceden sus ángulos mientras está abierto."
L["How long the windows stay open, cursor off them, before Auto-Minimize collapses them."] = "Cuánto tiempo permanecen abiertas las ventanas, con el cursor fuera de ellas, antes de que Auto-minimizar las contraiga."
L["How many decimal places the number carries."] = "Cuántos decimales lleva el número."
L["How many entries a row of the grid holds. 1 stacks them into a single column; %1$s -- the most slots an action menu can hold -- lays them out in a single row."] = "Cuántas entradas contiene una fila de la cuadrícula. 1 las apila en una sola columna; %1$s -- el máximo de ranuras que puede contener un menú de acciones -- las distribuye en una sola fila."
L["How many icons to show on the base row (the row that fills first and that Row Growth keeps in place). The rest go on the second row."] = "Cuántos iconos mostrar en la fila base (la fila que se llena primero y que Crecimiento de fila mantiene en su sitio). El resto van en la segunda fila."
L["How many icons to show on the bottom row. The rest go on the top row."] = "Cuántos iconos mostrar en la fila inferior. El resto van en la fila superior."
L["How many icons to show on the top row. The rest go on the bottom row."] = "Cuántos iconos mostrar en la fila superior. El resto van en la fila inferior."
L["How many pixels the custom effect extends beyond the icon."] = "Cuántos píxeles se extiende el efecto personalizado más allá del icono."
L["How much is trimmed from the icon's top and bottom, as a percentage per side. 10% is the classic cropped look."] = "Cuánto se recorta de la parte superior e inferior del icono, como porcentaje por lado. 10% es el aspecto recortado clásico."
L["How precise the coordinates read. More decimals make the block wider."] = "Con qué precisión se leen las coordenadas. Más decimales hacen el bloque más ancho."
L["How wide the block stays, whatever the zone is called."] = "Cuánto de ancho se mantiene el bloque, sea cual sea el nombre de la zona."
