L["Include your Blizz UI Enhanced settings from the Window Skins and Tooltips, Menus & Popups tabs. These are account-wide: if the importer opts in, they overwrite that player's settings across ALL of their profiles."] = "Incluye tus ajustes de Blizz UI Enhanced de las pestañas Skins de ventana y Tooltips, menús y ventanas emergentes. Son de toda la cuenta: si quien importa lo activa, sobrescriben los ajustes de ese jugador en TODOS sus perfiles."
L["Include your Cooldown Manager spell layout (which spells sit on which bars) plus all per-spell settings for any specs you choose."] = "Incluye el diseño de hechizos de tu Gestor de tiempos de reutilización (qué hechizos están en qué barras) más todos los ajustes por hechizo de las especializaciones que elijas."
L["Include your complete override setup: spec and conditional override values, groups, their custom Unlock Mode layouts, and Buff Manager overrides. On import this replaces the recipient's overrides entirely."] = "Incluye toda tu configuración de anulaciones: valores de anulación de especialización y condicionales, grupos, sus diseños personalizados del modo de desbloqueo y las anulaciones del gestor de beneficios. Al importar, esto sustituye por completo las anulaciones del destinatario."
