L["Keep"] = "Mantener"
L["Keep Action Bar 1 on its current page when you shapeshift, stealth, or change stance, instead of swapping to that form's bar.\n\nKeybinds follow what the bar shows, so the key always casts the icon you see. Press-and-hold repeat casting is turned off on Action Bar 1 while this is enabled."] = "Mantiene la Barra de acción 1 en su página actual cuando cambias de forma, entras en sigilo o cambias de postura, en lugar de pasar a la barra de esa forma.\n\nLos atajos de teclado siguen lo que muestra la barra, así que la tecla siempre lanza el icono que ves. El lanzamiento repetido al mantener pulsado se desactiva en la Barra de acción 1 mientras esto está activado."
L["Keep Action Bar 1 on its current page while skyriding, instead of swapping to the skyriding bar.\n\nYour skyriding abilities live on that bar, so put them on another bar before enabling this. Press-and-hold repeat casting is turned off on Action Bar 1 while this is enabled."] = "Mantiene la Barra de acción 1 en su página actual durante el vuelo aéreo, en lugar de pasar a la barra de vuelo aéreo.\n\nTus habilidades de vuelo aéreo están en esa barra, así que ponlas en otra barra antes de activar esto. El lanzamiento repetido al mantener pulsado se desactiva en la Barra de acción 1 mientras esto está activado."
L["Keep Buffs in Same Place"] = "Mantener beneficios en el mismo sitio"
L["Keep Colored (On CD)"] = "Mantener coloreado (en reutilización)"
L["Keep Enabled"] = "Mantener activado"
L["Keep Focus Full Opacity"] = "Mantener opacidad total del foco"
L["Keep Keys on Bar Swap (global)"] = "Mantener teclas al cambiar de barra (global)"
L["Keep Mine"] = "Mantener el mío"
L["Keep Raid Frames"] = "Mantener marcos de banda"
L["Keep keybind text identical when your action bar swaps -- rogue stealth, druid forms, skyriding. Also covers conditional macros like \"/cast [bonusbar:1] Backstab; Shadow Dance\", where the key would otherwise jump to whichever branch is live.\n\nThe key then only changes when you actually move the ability or rebind it.\n\nOn by default. Applies to every CDM bar at once."] = "Mantiene el texto del atajo de teclado idéntico cuando tu barra de acción cambia -- sigilo de pícaro, formas de druida, vuelo aéreo. También cubre macros condicionales como \"/cast [bonusbar:1] Puñalada trasera; Danza de las sombras\", donde la tecla de otro modo saltaría a la rama que esté activa.\n\nAsí la tecla solo cambia cuando realmente mueves la habilidad o la reasignas.\n\nActivado por defecto. Se aplica a todas las barras del CDM a la vez."
L["Keep the GCD bar visible (sitting empty) when no global cooldown is running, instead of hiding it."] = "Mantiene visible la barra del TGC (vacía) cuando no hay ningún tiempo de reutilización global en curso, en lugar de ocultarla."
L["Keep the cast bar visible (sitting empty) when you are not casting, instead of hiding it."] = "Mantiene visible la barra de lanzamiento (vacía) cuando no estás lanzando, en lugar de ocultarla."
L["Keep the item count visible and show 0 instead of hiding it when you have none of the item (e.g. potions, healthstone)."] = "Mantiene visible el recuento de objetos y muestra 0 en lugar de ocultarlo cuando no tienes ninguno del objeto (por ejemplo, pociones, piedra de salud)."
L["Keep the timer visible out of combat, showing the last fight's duration."] = "Mantiene visible el temporizador fuera de combate, mostrando la duración del último combate."
L["Keep this menu open when you let go of its keybind.\nPoint at an entry and press the Select Action key to use it.\nPress the menu's own keybind again, or Escape, to close it."] = "Mantiene este menú abierto cuando sueltas su atajo de teclado.\nApunta a una entrada y pulsa la tecla Seleccionar acción para usarla.\nPulsa de nuevo el atajo de teclado propio del menú, o Escape, para cerrarlo."
L["Keep your own UI scale. Off = apply the UI scale this profile was made with (changes the scale for all your characters)."] = "Mantiene tu propia escala de interfaz. Desactivado = aplica la escala de interfaz con la que se creó este perfil (cambia la escala de todos tus personajes)."
L["Keeps Artisan's Consortium Payouts closed while Shard of Dundun is at its maximum, then resumes automatic opening after you spend shards."] = "Mantiene cerrados los Pagos del Consorcio Artesano mientras el Fragmento de Dundun está al máximo, y reanuda la apertura automática después de gastar fragmentos." -- TODO: confirmar termo oficial
L["Keeps Blizzard's own buff and debuff display and turns off the built-in Buffs and Debuffs bars. Custom bars keep working."] = "Mantiene la visualización propia de beneficios y perjuicios de Blizzard y desactiva las barras integradas de Beneficios y Perjuicios. Las barras personalizadas siguen funcionando."
L["Keeps a saved signup note you can copy into the Sign Up dialog with the Copy button."] = "Mantiene una nota de inscripción guardada que puedes copiar en el diálogo de Inscripción con el botón Copiar."
L["Keeps the first row in place when the second row appears or disappears."] = "Mantiene la primera fila en su sitio cuando aparece o desaparece la segunda fila."
L["Keeps this bar fully visible while flying on a skyriding mount (or Druid Flight Form), or while it's paged onto the vehicle bar (Action Bar 1 while the player is in a vehicle), regardless of the Visibility mode above."] = "Mantiene esta barra totalmente visible mientras vuelas en una montura de vuelo aéreo (o Forma de vuelo de druida), o mientras está paginada en la barra de vehículo (Barra de acción 1 mientras el jugador está en un vehículo), sin importar el modo de Visibilidad de arriba."
L["Keeps your note text in the Sign Up dialog instead of clearing it each time you open it."] = "Mantiene el texto de tu nota en el diálogo de Inscripción en lugar de borrarlo cada vez que lo abres."
L["Key Already Bound"] = "Tecla ya asignada"
L["Keybind"] = "Atajo de teclado"

