L["List item categories in the bank sidebar the way the bags sidebar does -- groups such as The Armory with Weapons and Armor under them. Selecting one filters the grid to that category. Categories that split further list their parts as a third level while selected: Professions by profession, Armor by equipment slot, Trade Goods by material. Spans your character bank and warband together, so a category shows everything you own."] = "Lista las categorías de objetos en la barra lateral del banco igual que lo hace la barra lateral de las bolsas: grupos como El Arsenal con Armas y Armadura debajo. Seleccionar uno filtra la cuadrícula a esa categoría. Las categorías que se dividen más muestran sus partes como un tercer nivel al seleccionarlas: Profesiones por profesión, Armadura por ranura de equipo, Bienes comerciales por material. Abarca a la vez el banco de tu personaje y el de tu banda de guerra, de modo que una categoría muestra todo lo que posees."
L["Lists every group member against the consumables a raid expects -- flask, food, augment rune, vantus -- whenever a ready check starts, whoever started it."] = "Compara a cada miembro del grupo con los consumibles que se esperan en una banda (frasco, comida, runa de aumento, vantus) cada vez que se inicia una revisión de preparación, sin importar quién la haya iniciado."
L["Lists only the people something is actually wrong with, so a thirty-man roster becomes the three names you need to whisper. Someone whose client has not reported yet is not counted as missing."] = "Solo enumera a las personas con las que realmente hay un problema, de modo que una lista de treinta personas se convierte en los tres nombres a los que necesitas enviar un susurro. Alguien cuyo cliente aún no ha respondido no se cuenta como ausente."
