L["Makes this the override. It replaces the whole Visibility setting, so the conditions below no longer apply while it does. Click it again to remove the override."] = "Hace que esta sea la anulación. Reemplaza todo el ajuste de Visibilidad, por lo que las condiciones de abajo dejan de aplicarse mientras esté activa. Haz clic de nuevo para quitar la anulación."
