L["Not overridable. These conditions are shared and can only be changed while no override is being edited. An override replaces the Visibility setting outright -- Never, Always or Mouseover -- and ignores everything set here while it applies. Mouseover is sealed here too for this element: its hover mechanism follows the shared setting, so an override could only leave it shown."] = "No se puede anular. Estas condiciones son compartidas y solo se pueden cambiar mientras no se esté editando ninguna anulación. Una anulación reemplaza por completo el ajuste de Visibilidad --Nunca, Siempre o Al pasar el ratón-- e ignora todo lo configurado aquí mientras se aplica. El paso del ratón también está sellado aquí para este elemento: su mecanismo de aparición al pasar el cursor sigue el ajuste compartido, por lo que una anulación solo podría dejarlo siempre visible."
