L["Off (default): the cast bar fades with real transparency, matching the whole-frame Out of Range Alpha (best if you're colour-matching the frame and cast bar). On: the old behavior -- a black overlay dims the bar instead of fading it, which can't discolor a shielded/uninterruptible cast's tint but won't visually match the frame's fade."] = "Desactivado (por defecto): la barra de lanzamiento se desvanece con transparencia real, igualando la Opacidad fuera de alcance de todo el marco (ideal si estás combinando colores del marco y la barra de lanzamiento). Activado: el comportamiento antiguo: una superposición negra oscurece la barra en lugar de desvanecerla, lo cual no puede alterar el tinte de un lanzamiento protegido o ininterrumpible, pero no coincidirá visualmente con el desvanecimiento del marco."
