L["On quest mobs in the open world, replaces the quest icon with the objective progress (a kill quest shows 0/6, a percentage quest shows 50%). Falls back to the icon when no progress is available. Never shown in instances."] = "En los mobs de misión del mundo abierto, sustituye el icono de misión por el progreso del objetivo (una misión de eliminación muestra 0/6, una misión de porcentaje muestra 50%). Vuelve al icono cuando no hay progreso disponible. Nunca se muestra en instancias."
L["On quest mobs in the open world, replaces the quest icon with the objective progress (ex: kill quests show 0/6, percentage objectives show 50%)."] = "En los mobs de misión del mundo abierto, sustituye el icono de misión por el progreso del objetivo (ej.: las misiones de eliminación muestran 0/6, los objetivos de porcentaje muestran 50%)."
L["On"] = "Activado"
L["Once the lockout expires, show a Ready label on the icon in place of the countdown. The visibility rule above still applies."] = "Cuando expire el bloqueo, muestra una etiqueta de Listo en el icono en lugar de la cuenta atrás. La regla de visibilidad de arriba sigue aplicándose."
