L["Only Show Dispellable"] = "Mostrar solo disipable"
L["Only Show Numbers"] = "Mostrar solo números"
L["Only Show When Hidden"] = "Mostrar solo cuando esté oculto"
L["Only Show for % Health"] = "Mostrar solo por % de vida"
L["Only Show in Housing"] = "Mostrar solo en Vivienda" -- TODO: confirmar termo oficial (Housing)
L["Only Show in Instances"] = "Mostrar solo en instancias"
L["Only Show when Mounted"] = "Mostrar solo cuando estés montado"
L["Only Target Out of Combat"] = "Solo seleccionar objetivo fuera de combate"
L["Only Tracked Auras"] = "Solo auras seguidas"
L["Only With Multiple Boss Frames"] = "Solo con múltiples marcos de jefe"
L["Only affects the vertical (Right/Left Edge) positions"] = "Solo afecta a las posiciones verticales (borde derecho/izquierdo)"
L["Only applies when Name > Target is selected."] = "Solo se aplica cuando está seleccionado Nombre > Objetivo."
L["Only applies when Name or Name > Target is selected."] = "Solo se aplica cuando está seleccionado Nombre o Nombre > Objetivo."
L["Only applies when the selected text includes a Name."] = "Solo se aplica cuando el texto seleccionado incluye un Nombre."
L["Only available in Detached or Inside modes"] = "Solo disponible en los modos Separado o Interior"
L["Only available when Portrait Mode is Detached"] = "Solo disponible cuando el modo de retrato es Separado"
L["Only available with Custom fill color"] = "Solo disponible con color de relleno personalizado"
L["Only available with the 'From' direction -- it highlights the pips at/above the threshold."] = "Solo disponible con la dirección 'Desde': resalta los indicadores en o por encima del umbral."
L["Only color at/above threshold"] = "Colorear solo en/sobre el umbral"
L["Only glow once the buff's stack count matches the comparison set via the gear."] = "Solo resplandece cuando la cantidad de acumulación del beneficio coincide con la comparación establecida mediante el engranaje."
L["Only if Power Bar Hidden"] = "Solo si la barra de poder está oculta"
L["Only in Combat"] = "Solo en combate"
L["Only play alerts while in combat."] = "Solo reproducir alertas mientras estés en combate."
L["Only preset or custom buff bars can be added to all specs"] = "Solo las barras de beneficios preestablecidas o personalizadas se pueden añadir a todas las especializaciones"
L["Only recolor the fill when more than one boss frame is active at once (a multi-boss phase). With a single boss frame up, it keeps its normal color even while targeted. Off (default) recolors regardless of how many boss frames are active."] = "Solo vuelve a colorear el relleno cuando hay más de un marco de jefe activo a la vez (una fase con varios jefes). Con un solo marco de jefe activo, mantiene su color normal incluso al seleccionarlo como objetivo. Desactivado (por defecto) vuelve a colorear sin importar cuántos marcos de jefe estén activos."
L["Only show buffs cast by you."] = "Mostrar solo beneficios lanzados por ti."
L["Only show debuffs that have a duration, excluding permanent ones. Combines with the filters below; checked alone it shows every timed debuff."] = "Mostrar solo perjuicios que tengan duración, excluyendo los permanentes. Se combina con los filtros de abajo; marcado solo, muestra todos los perjuicios cronometrados."
L["Only show debuffs whose full duration is at most this many seconds. Combines with the filters; Unlimited applies no cap."] = "Mostrar solo perjuicios cuya duración total sea de como máximo esta cantidad de segundos. Se combina con los filtros; Ilimitado no aplica ningún límite."
L["Only show the GCD bar for instant-cast abilities. While hard-casting or channeling a spell, the bar stays hidden (the cast bar already shows that progress)."] = "Mostrar la barra del TGC solo para habilidades de lanzamiento instantáneo. Mientras lanzas o canalizas un hechizo, la barra permanece oculta (la barra de lanzamiento ya muestra ese progreso)."
L["Only show the GCD bar while in a dungeon, raid, arena or battleground."] = "Mostrar la barra del TGC solo en mazmorra, banda, arena o campo de batalla."
L["Only show the alert while in combat."] = "Mostrar la alerta solo en combate."
L["Only show the cast bar while a cast is in progress; hide it the rest of the time."] = "Mostrar la barra de lanzamiento solo mientras haya un lanzamiento en curso; ocultarla el resto del tiempo."
L["Only show these buffs when you cast them."] = "Mostrar estos beneficios solo cuando los lances."
L["Only show this bar while the tracked buff/cooldown is active. Turn off to keep an empty bar on screen at all times."] = "Mostrar esta barra solo mientras el beneficio/tiempo de reutilización seguido esté activo. Desactívalo para mantener una barra vacía en pantalla en todo momento."
L["Only show this bar while the tracked buff/cooldown is active. Unchecked keeps an empty bar on screen at all times."] = "Mostrar esta barra solo mientras el beneficio/tiempo de reutilización seguido esté activo. Si está desmarcado, se mantiene una barra vacía en pantalla en todo momento."
L["Only shows the GCD circle while you are in combat."] = "Muestra el círculo del TGC solo mientras estás en combate."
L["Only shows the cast bar circle while you are in combat."] = "Muestra el círculo de la barra de lanzamiento solo mientras estás en combate."
L["Only shows the cursor circle while the mouse is hidden -- that is, while you hold the left and/or right mouse button to pan the camera or move your character."] = "Muestra el círculo del cursor solo mientras el ratón está oculto, es decir, mientras mantienes pulsado el botón izquierdo o derecho del ratón para desplazar la cámara o mover a tu personaje."
L["Only shows the cursor circle while you are in combat."] = "Muestra el círculo del cursor solo mientras estás en combate."
L["Only while AIRBORNE on a glide-capable mount or flight form. For the mount itself, ground included, use Skyriding Mount."] = "Solo mientras estás EN EL AIRE con una montura capaz de planear o una forma de vuelo. Para la montura en sí, incluyendo en el suelo, usa Montura de vuelo aéreo."
L["Only while airborne on a skyriding mount."] = "Solo mientras estás en el aire con una montura de vuelo aéreo."
L["Only works for Blizzard's whitelisted healer spell IDs (non-private auras)."] = "Solo funciona para los ID de hechizo de sanador incluidos en la lista blanca de Blizzard (auras no privadas)."
L["Only works outside of Instances"] = "Solo funciona fuera de instancias"
L["Opacity of the Button Overlay tint."] = "Opacidad del tinte de la Superposición de botón."
L["Opacity of the background overlay. 0 removes it entirely; the 9.0.7 default is 62."] = "Opacidad de la superposición de fondo. 0 la elimina por completo; el valor predeterminado de la 9.0.7 es 62."
L["Opacity of the bar fill; below 100 the world shows through the fill instead of the background."] = "Opacidad del relleno de la barra; por debajo de 100 el mundo se ve a través del relleno en lugar del fondo."
L["Opacity of the bar's background; the swatch picks the Modern color."] = "Opacidad del fondo de la barra; la muestra de color elige el color Moderno."
L["Opacity of the cast bar fill; below 100 the world shows through the fill instead of the background."] = "Opacidad del relleno de la barra de lanzamiento; por debajo de 100 el mundo se ve a través del relleno en lugar del fondo."
L["Opacity of the cooldown swipe (the dark radial sweep); use the swatch to set its colour."] = "Opacidad del barrido de reutilización (el barrido radial oscuro); usa la muestra de color para definir su color."
L["Opacity of the resource fill; below 100 the world shows through the fill instead of the background."] = "Opacidad del relleno de recurso; por debajo de 100 el mundo se ve a través del relleno en lugar del fondo."
L["Opacity used for enemy nameplates outside the selected attack range."] = "Opacidad usada para las placas de nombre enemigas fuera del alcance de ataque seleccionado."
