L["Raid only. Left-click the Durability column's header icon anytime to use the Auto-Hammer (item 132514) -- no one needs to be low first. When a player's Durability reading drops to 25% or below, their name blinks as a heads-up, but that's just a warning, not a requirement to click."] = "Solo banda. Haz clic izquierdo en el icono de la cabecera de la columna Durabilidad en cualquier momento para usar el Automartillo (objeto 132514): no es necesario que nadie esté bajo primero. Cuando la durabilidad de un jugador cae al 25% o menos, su nombre parpadea como aviso, pero eso es solo una advertencia, no un requisito para hacer clic." -- TODO: confirmar termo oficial (Auto-Hammer)
L["Raid only. Left-click the Food column's header icon anytime to drop a feast at your own feet: Feast of Knowledge, falling back to Amani Cornucopia and then Loa's Gathering depending on what's in your bags. Disarmed while you already have a Well Fed buff active, so there's no wasted click."] = "Solo banda. Haz clic izquierdo en el icono de la cabecera de la columna Comida en cualquier momento para dejar un festín a tus pies: Festín del conocimiento, recurriendo a Cornucopia amani y luego a Recolecta de los loa según lo que tengas en las bolsas. Se desactiva mientras ya tengas activo un beneficio de Bien alimentado, para que no se desperdicie el clic." -- TODO: confirmar termo oficial (Feast of Knowledge/Amani Cornucopia/Loa's Gathering/Well Fed)
