L["Reminder threshold while you are in a dungeon before a Mythic+ key starts (Mythic 0 / keystone lobby). Set it high enough that you top up buffs and food before pulling, so you begin the key with enough duration to last it.\n0 = only when fully expired.\nIgnored once the key is active or you are in combat (then only when the buff is fully gone)."] = "Umbral de recordatorio mientras estás en una mazmorra antes de que empiece una llave de Mítica+ (Mítico 0 / vestíbulo de llave). Pon un valor lo bastante alto para que renueves beneficios y comida antes de iniciar el pull, de modo que empieces la llave con suficiente duración para que dure.\n0 = solo cuando haya expirado por completo.\nSe ignora una vez que la llave está activa o estás en combate (entonces solo cuando el beneficio haya desaparecido por completo)." -- JARGAO (Pull)
L["Reminders are always hidden in rested areas (cities and inns)."] = "Los recordatorios siempre están ocultos en zonas de descanso (ciudades y posadas)."
