L["Replaces Buff Glow: the icon glows when its stack count matches the comparison below, using this spell's Buff Glow style (Modern WoW Glow if none is set)."] = "Sustituye Resplandor de beneficio: el icono resplandece cuando su cantidad de acumulación coincide con la comparación de abajo, usando el estilo de Resplandor de beneficio de este hechizo (Resplandor moderno de WoW si no hay ninguno definido)."
L["Replaces the class resource bar with an Ignore Pain tracker: the fill shows your current absorb amount scaled against your maximum health, and the bar text shows the absorb value."] = "Sustituye la barra de recurso de clase por un rastreador de Ignorar el Dolor: el relleno muestra tu cantidad actual de absorción a escala con tu vida máxima, y el texto de la barra muestra el valor de absorción." -- TODO: confirmar termo oficial (Ignore Pain)
L["Replaces the class resource bar with an Ironfur tracker. Each Ironfur cast adds a hash line that slides from right to left as its buff decays. Duration is talent-aware (Ursoc's Endurance and Guardian of Elune)."] = "Sustituye la barra de recurso de clase por un rastreador de Piel de hierro. Cada lanzamiento de Piel de hierro añade una línea de marca que se desliza de derecha a izquierda mientras su beneficio decae. La duración tiene en cuenta los talentos (Resistencia de Ursoc y Guardián de Elune)." -- TODO: confirmar termo oficial (Ironfur/Ursoc's Endurance/Guardian of Elune)
L["Replaces the spendable amount with the crests you have earned this season, out of the season cap. The tooltip lists both numbers side by side."] = "Sustituye la cantidad disponible por las crestas que has ganado esta temporada, del límite de la temporada. El tooltip muestra ambos números uno junto al otro."
