L["Restyle Blizzard's chat bubbles for the channels you pick beside this.\n\nEllesmereUI keeps Blizzard's bubbles switched on and draws over them, so every bubble stays where the game put it, including the one over your own head. Nameplates are not involved and do not need to be visible.\n\nChannels you leave off keep Blizzard's own look."] = "Cambia el estilo de las burbujas de chat de Blizzard para los canales que elijas junto a esto.\n\nEllesmereUI mantiene activadas las burbujas de Blizzard y dibuja sobre ellas, así que cada burbuja permanece donde el juego la puso, incluida la que está sobre tu propia cabeza. Las placas de nombre no están implicadas y no necesitan estar visibles.\n\nLos canales que dejes desactivados mantienen el aspecto propio de Blizzard."
L["Restyles Blizzard's on-screen progress bars (event objectives, nameplate counters) to the EUI look. Requires reload to apply.\n\nThese bars are drawn over rather than modified, so if the game ever reports their contents as protected the original bar is shown instead.\n\nUse the cog to set a minimum size, so bars on shrunken nameplates stay readable."] = "Cambia el estilo de las barras de progreso en pantalla de Blizzard (objetivos de evento, contadores de placa de nombre) al aspecto de EUI. Requiere recargar para aplicarse.\n\nEstas barras se dibujan por encima en lugar de modificarse, así que si el juego alguna vez informa que su contenido está protegido, se muestra la barra original en su lugar.\n\nUsa el engranaje para establecer un tamaño mínimo, para que las barras en placas de nombre reducidas sigan siendo legibles."
