L["Scales the custom tooltips shown by the unique minimap buttons (Great Vault, friends, calendar, mail, tracking)."] = "Escala los tooltips personalizados que muestran los botones exclusivos del minimapa (Gran Bóveda, amigos, calendario, correo, seguimiento)."
L["Scales the font size of reskinned Blizzard tooltips, menus, and popups."] = "Escala el tamaño de fuente de los tooltips, menús y ventanas emergentes de Blizzard con reskin."
