L["Scales the size of Blizzard's default game text (menus, tooltips, quest log, and more). Requires a UI reload."] = "Escala el tamaño del texto de juego predeterminado de Blizzard (menús, tooltips, registro de misiones y más). Requiere recargar la interfaz."
