L["Scales the tracking blips drawn on the map (herbs, ore, quest dots). The map itself keeps its size; other minimap elements are unaffected."] = "Escala los puntos de seguimiento dibujados en el mapa (hierbas, mineral, puntos de misión). El mapa en sí mantiene su tamaño; los demás elementos del minimapa no se ven afectados."
