L["Seconds counts the time down in tenths. GCD Count counts whole global cooldowns instead, so inside Arcane Soul it reads as the number of Arcane Barrages that still fit, ending on a coloured LAST. Seconds + GCD in Soul mixes the two: tenths counting down to the window, Barrage count once it opens."] = "Segundos cuenta el tiempo en décimas. Recuento de TGC cuenta tiempos globales de reutilización completos en su lugar, de modo que dentro de Alma arcana se lee como el número de Ráfagas arcanas que todavía caben, terminando en un ÚLTIMO coloreado. Segundos + TGC en Alma mezcla ambos: décimas contando hacia la ventana, recuento de Ráfagas una vez que se abre." -- TODO: confirmar termo oficial (Arcane Barrage)
