L["Sets the accent color used across all EllesmereUI elements (tabs, glows, highlights, borders). Defaults to your theme color."] = "Establece el color de acento usado en todos los elementos de EllesmereUI (pestañas, resplandores, resaltados, bordes). Usa por defecto el color de tu tema."
L["Sets the font for the names that float above players, NPCs and enemies in the world.\n\nSeparate from Global Font - changing this does not affect the rest of the UI, and Global Font does not affect it.\n\nBlizzard Default leaves the name text completely untouched.\n\n|cffff4d4dRequires a re-log or restart of WoW to take effect.|r"] = "Establece la fuente de los nombres que flotan sobre jugadores, PNJ y enemigos en el mundo.\n\nEs independiente de la Fuente global: cambiar esto no afecta al resto de la interfaz, y la Fuente global no lo afecta a él.\n\nPredeterminado de Blizzard deja el texto de nombre completamente intacto.\n\n|cffff4d4dRequiere volver a conectar o reiniciar WoW para que surta efecto.|r"
L["Sets the scale of the entire game UI. Lower values make everything smaller, higher values make everything larger."] = "Establece la escala de toda la interfaz del juego. Los valores más bajos hacen que todo sea más pequeño, los valores más altos hacen que todo sea más grande."
