L["Show a 1-decimal countdown (2.7) below Threshold Seconds."] = "Mostrar una cuenta atrás con 1 decimal (2.7) por debajo de los segundos de umbral."
L["Show a 1-decimal countdown on presets and custom spell/item IDs when under the cog's Seconds Left threshold -- their active state on cooldown/utility bars, their buff duration on buff bars (both are hardcoded, so the remaining time is exact)."] = "Muestra una cuenta atrás con 1 decimal en los ID de hechizo/objeto predefinidos y personalizados cuando están por debajo del umbral de Segundos restantes del engranaje: su estado activo en las barras de reutilización/utilidad, su duración de beneficio en las barras de beneficios (ambos están codificados, por lo que el tiempo restante es exacto)."
L["Show a glow on icons when the remaining duration is in the pandemic window (last 30%)"] = "Muestra un resplandor en los iconos cuando la duración restante está en la ventana de pandemia (últimos 30%)"
L["Show a glow on the bar when the remaining duration is in the pandemic window (last 30%)"] = "Muestra un resplandor en la barra cuando la duración restante está en la ventana de pandemia (últimos 30%)"
L["Show a glow on the cast bar when the enemy is casting a spell Blizzard marks as important."] = "Muestra un resplandor en la barra de lanzamiento cuando el enemigo está lanzando un hechizo que Blizzard marca como importante."
L["Show a panel of equipped-gear sockets on the character sheet; click a socket to gem it."] = "Muestra un panel con los engastes del equipo equipado en la ficha de personaje; haz clic en un engaste para colocarle una gema."
L["Show a pulsing dot on the Patch Notes button whenever EllesmereUI updates to a new version."] = "Muestra un punto pulsante en el botón de notas del parche cada vez que EllesmereUI se actualiza a una nueva versión."
L["Show a reminder when you don't have an active pet summoned. Only applies to pet classes (Hunter, Warlock, Death Knight, Mage)."] = "Muestra un recordatorio cuando no tienes una mascota activa invocada. Solo se aplica a las clases con mascota (Cazador, Brujo, Caballero de la Muerte, Mago)."
L["Show a reminder when your Demonology Warlock has the wrong pet summoned (not Felguard)."] = "Muestra un recordatorio cuando tu brujo de demonología tiene invocada la mascota equivocada (que no sea el guardia vil)."
L["Show a reminder when your active pet is set to Passive stance. Only applies to pet classes (Hunter, Warlock, Death Knight, Mage)."] = "Muestra un recordatorio cuando tu mascota activa está en postura pasiva. Solo se aplica a las clases con mascota (Cazador, Brujo, Caballero de la Muerte, Mago)."
L["Show a shield icon on the cast bar when an enemy's cast cannot be interrupted."] = "Muestra un icono de escudo en la barra de lanzamiento cuando el lanzamiento de un enemigo no se puede interrumpir."
L["Show a shield icon on the cast bar when the cast cannot be interrupted."] = "Muestra un icono de escudo en la barra de lanzamiento cuando el lanzamiento no se puede interrumpir."
L["Show a small glowing spark that moves along the leading edge of the fill."] = "Muestra una pequeña chispa brillante que se desplaza por el borde delantero del relleno."
L["Show a tracked buff in this slot while it is active."] = "Muestra un beneficio seguido en esta ranura mientras esté activo."
L["Show absorbs on Boss Frames, styled independently from the Boss tab's own Absorbs section."] = "Muestra las absorciones en los Marcos de jefe, con un estilo independiente de la propia sección Absorciones de la pestaña Jefe."
L["Show as"] = "Mostrar como"
L["Show aura tooltips when hovering buff and debuff icons on all unit frames except boss frames."] = "Muestra los tooltips de aura al pasar el ratón sobre los iconos de beneficio y perjuicio en todos los marcos de unidad excepto los marcos de jefe."
L["Show aura tooltips when hovering buff and debuff icons on boss frames."] = "Muestra los tooltips de aura al pasar el ratón sobre los iconos de beneficio y perjuicio en los marcos de jefe."
L["Show aura tooltips when hovering this bar's icons."] = "Muestra los tooltips de aura al pasar el ratón sobre los iconos de esta barra."
L["Show black backgrounds behind minimap indicator buttons (tracking, calendar, mail, crafting, addon buttons, flyout toggle)."] = "Muestra fondos negros detrás de los botones indicadores del minimapa (seguimiento, calendario, correo, fabricación, botones de addon, interruptor de menú desplegable)."
L["Show button backgrounds even if a spell is not assigned to that slot."] = "Muestra los fondos de los botones incluso si no hay un hechizo asignado a esa ranura."
L["Show combat indicator preview"] = "Mostrar vista previa del indicador de combate"
L["Show copies of the same item that sit in separate bag slots as one icon with their counts added together. Turn this off to keep every slot separate, for example when you deliberately split stacks. Merging is always paused while the mail, trade, auction house, bank or guild bank window is open, since those take one bag slot at a time."] = "Muestra las copias de un mismo objeto que ocupan ranuras de bolsa separadas como un único icono con sus cantidades sumadas. Desactiva esto para mantener cada ranura separada, por ejemplo cuando divides pilas a propósito. La combinación siempre se pausa mientras está abierta la ventana de correo, comercio, casa de subastas, banco o banco de hermandad, ya que estas ocupan una ranura de bolsa a la vez."
L["Show debuffs on preview"] = "Mostrar perjuicios en la vista previa"
L["Show defensives on preview"] = "Mostrar defensivos en la vista previa"
