L["Show duration and stack count text on buff and debuff icons."] = "Muestra el texto de duración y número de pilas en los iconos de beneficio y perjuicio."
L["Show each enchant's name as text (colored to match that item's item level) instead of its icon. The name normally appears only when hovering the icon."] = "Muestra el nombre de cada encantamiento como texto (coloreado según el nivel de objeto de ese objeto) en lugar de su icono. El nombre normalmente solo aparece al pasar el ratón sobre el icono."
L["Show equipped trinkets even if they don't have an on-use effect."] = "Muestra los abalorios equipados aunque no tengan un efecto de uso."
L["Show every buff that has a duration (hides permanent buffs). Use the Hide lane below to remove specific filters."] = "Muestra todos los beneficios que tengan duración (oculta los beneficios permanentes). Usa el carril Ocultar de abajo para eliminar filtros específicos."
L["Show every buff that has a duration (hides permanent buffs). While this is on, checked filters below are hidden instead of added."] = "Muestra todos los beneficios que tengan duración (oculta los beneficios permanentes). Mientras esto esté activado, los filtros marcados abajo se ocultan en lugar de añadirse."
L["Show every buff. Use the Hide lane below to remove specific filters."] = "Muestra todos los beneficios. Usa el carril Ocultar de abajo para eliminar filtros específicos."
L["Show every buff. While this is on, checked filters below are hidden from the bar instead of added."] = "Muestra todos los beneficios. Mientras esto esté activado, los filtros marcados abajo se ocultan de la barra en lugar de añadirse."
L["Show every buff. While this is on, checked filters below are hidden from the frame instead of added."] = "Muestra todos los beneficios. Mientras esto esté activado, los filtros marcados abajo se ocultan del marco en lugar de añadirse."
L["Show every debuff in the base grid. The Base Filters dropdown is ignored while this is on."] = "Muestra todos los perjuicios en la cuadrícula base. El menú desplegable Filtros base se ignora mientras esto esté activado."
L["Show every debuff in this indicator. Use the Hide lane below to remove specific filters."] = "Muestra todos los perjuicios en este indicador. Usa el carril Ocultar de abajo para eliminar filtros específicos."
L["Show every debuff. Use the Hide lane below to remove specific filters."] = "Muestra todos los perjuicios. Usa el carril Ocultar de abajo para eliminar filtros específicos."
L["Show every debuff. While this is on, checked filters below are hidden from the bar instead of added."] = "Muestra todos los perjuicios. Mientras esto esté activado, los filtros marcados abajo se ocultan de la barra en lugar de añadirse."
L["Show every debuff. While this is on, checked filters below are hidden from the frame instead of added."] = "Muestra todos los perjuicios. Mientras esto esté activado, los filtros marcados abajo se ocultan del marco en lugar de añadirse."
L["Show every debuff. While this is on, checked filters below are hidden from the grid instead of added."] = "Muestra todos los perjuicios. Mientras esto esté activado, los filtros marcados abajo se ocultan de la cuadrícula en lugar de añadirse."
L["Show gear tiles for items already at their maximum item level."] = "Muestra los mosaicos de equipo para objetos que ya están en su nivel de objeto máximo."
L["Show heal absorb preview"] = "Mostrar vista previa de absorción de curación"
L["Show helpful tip text on Pinned Items and Recent Items category headers."] = "Muestra texto de ayuda en los encabezados de categoría de Objetos fijados y Objetos recientes."
