L["Show one decimal place on health text: health values like 240.5k and health percent like 77.3%. Power text is unaffected. Off by default."] = "Muestra un decimal en el texto de vida: valores de vida como 240.5k y porcentaje de vida como 77.3%. El texto de poder no se ve afectado. Desactivado de forma predeterminada."
L["Show one plain cast bar per enemy nameplate that is casting, gathered into a single movable group with the spell name, its target, and the cast timer."] = "Muestra una barra de lanzamiento sencilla por cada placa de nombre enemiga que esté lanzando, agrupadas en un único grupo movible con el nombre del hechizo, su objetivo y el temporizador de lanzamiento."
L["Show one sub-category per equipment set (named after the set) nested under Item Set Gear. Gear in several sets goes to the first one."] = "Muestra una subcategoría por cada conjunto de equipo (con el nombre del conjunto) anidada bajo Equipo de conjunto. El equipo que pertenece a varios conjuntos va al primero."
L["Show one-time video guide badges next to new or complex features. Each badge disappears forever once clicked."] = "Muestra insignias de guía en vídeo de un solo uso junto a funciones nuevas o complejas. Cada insignia desaparece para siempre en cuanto se hace clic en ella."
L["Show only while in a dungeon, raid, arena or battleground. Combine with Combat to show only during instanced combat."] = "Muestra solo mientras estás en una mazmorra, banda, arena o campo de batalla. Combínalo con Combate para mostrar solo durante el combate en instancias."
L["Show only while in combat. Combine with Instances to show only during instanced combat."] = "Muestra solo mientras estás en combate. Combínalo con Instancias para mostrar solo durante el combate en instancias."
L["Show page up/down arrows next to Action Bar 1 for cycling through action bar pages 1-6."] = "Muestra flechas de página arriba/abajo junto a la Barra de acción 1 para recorrer las páginas 1-6 de la barra de acción."
L["Show player nicknames from supported addons instead of character names on your main frames."] = "Muestra los apodos de jugador de addons compatibles en lugar de los nombres de personaje en tus marcos principales."
L["Show private auras on preview"] = "Mostrar auras privadas en la vista previa"
L["Show quest objective progress on nameplates for open-world mobs."] = "Muestra el progreso del objetivo de misión en las placas de nombre de los mobs de mundo abierto."
L["Show reminders when remaining buff time is below this many minutes.\n0 = only when fully expired.\nIgnored in combat and during Mythic+ keys (then only when the buff is gone)."] = "Muestra recordatorios cuando el tiempo restante del beneficio esté por debajo de estos minutos.\n0 = solo cuando haya expirado por completo.\nSe ignora en combate y durante las llaves de Mítico+ (entonces solo cuando el beneficio haya desaparecido)."
L["Show rune count in center and remove recharge text/animation"] = "Mostrar el número de runas en el centro y quitar el texto/animación de recarga"
L["Show rune count in center and remove recharging text/animation"] = "Mostrar el número de runas en el centro y quitar el texto/animación de recarga"
L["Show shield effects on preview"] = "Mostrar efectos de escudo en la vista previa"
L["Show special reminders while out in the open world."] = "Muestra recordatorios especiales mientras estás en el mundo abierto."
L["Show special reminders while out in the open world.\nReminders are always hidden in rested areas (cities and inns)."] = "Muestra recordatorios especiales mientras estás en el mundo abierto.\nLos recordatorios siempre se ocultan en zonas de descanso (ciudades y posadas)."
L["Show successful interrupt lockouts in the crowd-control icon slot.\n\nDue to addon restrictions, the duration shown is a generic 4 seconds for all classes, so it is not 100% accurate."] = "Muestra los bloqueos de interrupción exitosos en la ranura de icono de control de masas.\n\nDebido a restricciones del addon, la duración mostrada es un valor genérico de 4 segundos para todas las clases, por lo que no es 100% precisa."
L["Show targeted spells on preview"] = "Mostrar hechizos dirigidos en la vista previa"
L["Show the FocusKick bar on your current target's nameplate instead of your focus target's nameplate."] = "Muestra la barra de FocusKick en la placa de nombre de tu objetivo actual en lugar de la de tu objetivo de foco."
L["Show the Mythic+ teleport section in the tooltip. Ready rows are click-to-teleport."] = "Muestra la sección de teletransporte de Mítico+ en el tooltip. Las filas listas permiten teletransportarte con un clic."
L["Show the Pinned Items category in the sidebar and content grid."] = "Muestra la categoría Objetos fijados en la barra lateral y la cuadrícula de contenido."
L["Show the Recent Items category in the sidebar and content grid for newly acquired items."] = "Muestra la categoría Objetos recientes en la barra lateral y la cuadrícula de contenido para objetos adquiridos recientemente."
L["Show the Sated/Exhaustion lockout countdown on the icon."] = "Muestra la cuenta atrás del bloqueo de Saciado/Extenuación en el icono." -- TODO: confirmar termo oficial (Exhaustion)
L["Show the bar full of its fill color while no global cooldown is running, instead of the background color."] = "Muestra la barra llena con su color de relleno mientras no haya ningún tiempo de reutilización global en curso, en lugar del color de fondo."
L["Show the border style and size controls for the timer bars."] = "Muestra los controles de estilo y tamaño de borde de las barras de temporizador."
L["Show the bright spark at the leading edge of the cast bar fill."] = "Muestra la chispa brillante en el borde delantero del relleno de la barra de lanzamiento."
L["Show the charge and stack counters on this bar's icons."] = "Muestra los contadores de carga y pila en los iconos de esta barra."
L["Show the crafted quality rank on tracked items, matching the rank icon on the action bars. Items with no crafted quality are unaffected. Only shown while the item is owned."] = "Muestra el rango de calidad de fabricación en los objetos seguidos, a juego con el icono de rango de las barras de acción. Los objetos sin calidad de fabricación no se ven afectados. Solo se muestra mientras posees el objeto."
L["Show the enemy's raid target marker to the left of the spell name."] = "Muestra el marcador de objetivo de banda del enemigo a la izquierda del nombre del hechizo."
L["Show the expansion landing page (Omnium Folio) button at the bottom-left of the minimap. Use the cog to nudge its position."] = "Muestra el botón de la página de inicio de la expansión (Folio Omnium) en la parte inferior izquierda del minimapa. Usa el engranaje para ajustar su posición."
L["Show the expansion landing page (Omnium Folio) button on the minimap. Use the cog to choose its corner and nudge its position."] = "Muestra el botón de la página de inicio de la expansión (Folio Omnium) en el minimapa. Usa el engranaje para elegir su esquina y ajustar su posición."
L["Show the game's spell tooltip when you hover a spell in a breakdown window."] = "Muestra el tooltip de hechizo del juego al pasar el ratón sobre un hechizo en una ventana de desglose."
L["Show the leader/assistant icon while you are in combat. Disable to hide it during combat."] = "Muestra el icono de líder/asistente mientras estás en combate. Desactívalo para ocultarlo durante el combate."
L["Show the main frames' hover highlight border on this frame. Turn off so this frame never recolors on mouseover. No effect when Highlight is off in the main frames' Hover Borders."] = "Muestra el borde de resaltado al pasar el ratón de los marcos principales en este marco. Desactívalo para que este marco nunca cambie de color al pasar el ratón. No tiene efecto si Resaltado está desactivado en los Bordes al pasar el ratón de los marcos principales."
L["Show the name of who the boss is casting on."] = "Muestra el nombre de a quién está lanzando el jefe."
L["Show the part of an absorb that exceeds your empty health and backfills over your current health. When off, absorbs only fill the empty part of the health bar."] = "Muestra la parte de una absorción que excede tu vida vacía y se rellena hacia atrás sobre tu vida actual. Cuando está desactivado, las absorciones solo rellenan la parte vacía de la barra de vida."
L["Show the part of an absorb that exceeds your empty health and backfills over your current health. When off, absorbs only fill the empty part of the health bar; on Default Blizz Frames the glow line stays pinned at the right edge."] = "Muestra la parte de una absorción que excede tu vida vacía y se rellena hacia atrás sobre tu vida actual. Cuando está desactivado, las absorciones solo rellenan la parte vacía de la barra de vida; en los Marcos predeterminados de Blizz, la línea de resplandor permanece fija en el borde derecho."
L["Show the pet frame whenever you have a pet, ignoring the Player frame's visibility settings."] = "Muestra el marco de mascota siempre que tengas una mascota, ignorando los ajustes de visibilidad del marco de Jugador."
L["Show the player's title inline with their name, and/or their guild on a line below it, on friendly nameplates."] = "Muestra el título del jugador junto a su nombre, o su hermandad en una línea debajo de él, en las placas de nombre amistosas."
L["Show the player's title or guild in a smaller line below their name on friendly nameplates."] = "Muestra el título o la hermandad del jugador en una línea más pequeña debajo de su nombre en las placas de nombre amistosas."
L["Show the recharge countdown on charge spells while a charge is still banked. When off, the recharge timer only appears at 0 charges (Blizzard default)."] = "Muestra la cuenta atrás de recarga en los hechizos de carga mientras aún queda una carga disponible. Cuando está desactivado, el temporizador de recarga solo aparece con 0 cargas (predeterminado de Blizzard)."
L["Show the resource text only while the power bar is hidden - disabled, filtered off for this spec, a spec with no power, or hidden by \"Hide Power Bar if Resource\". Off = always show the text."] = "Muestra el texto de recurso solo mientras la barra de poder está oculta: desactivada, filtrada para esta especialización, una especialización sin poder, u oculta por \"Ocultar barra de poder si hay recurso\". Desactivado = mostrar siempre el texto."
L["Show the rotating cooldown edge on every cooldown in this bar, not just while a charge is recharging. Hide Recharge Edge still overrides this for individual charge spells."] = "Muestra el borde giratorio de reutilización en todos los tiempos de reutilización de esta barra, no solo mientras se recarga una carga. Ocultar borde de recarga sigue teniendo prioridad sobre esto para hechizos de carga individuales."
L["Show the seasonal Earned / Cap column in the crest table."] = "Muestra la columna de Ganado / Límite de temporada en la tabla de crestas."
L["Show the selected action's name next to the selected icon."] = "Muestra el nombre de la acción seleccionada junto al icono seleccionado."
L["Show the tracker as the Rebirth icon or as a compact text line with charges and time until the next one."] = "Muestra el seguimiento como el icono de Renacimiento o como una línea de texto compacta con cargas y tiempo hasta la siguiente."
L["Show the unit's tooltip when hovering the frame itself."] = "Muestra el tooltip de la unidad al pasar el ratón sobre el propio marco."
L["Show this indicator's buffs in the exact order you arrange (the first 10 arranged buffs are guaranteed; any beyond follow the default sorting)."] = "Muestra los beneficios de este indicador en el orden exacto que organices (los primeros 10 beneficios organizados están garantizados; los demás siguen el orden predeterminado)."
L["Show this indicator's buffs on every spec of your class, not only this spec."] = "Muestra los beneficios de este indicador en todas las especializaciones de tu clase, no solo en esta."
L["Show top 15 entries instead of 8."] = "Muestra las 15 primeras entradas en lugar de 8."
L["Show total equipped durability above the character model, colored from green to red."] = "Muestra la durabilidad total del equipo sobre el modelo del personaje, coloreada de verde a rojo."
L["Show weapon oil and imbue icons at the front of this bar. They are weapon enchants rather than auras, so they show independently of the options above -- and the aura grid is shifted inward to make room for them, with every row shifting over by the same amount."] = "Muestra los iconos de aceite de arma e imbuidos al principio de esta barra. Son encantamientos de arma en lugar de auras, por lo que se muestran independientemente de las opciones anteriores; y la cuadrícula de auras se desplaza hacia dentro para hacerles sitio, con todas las filas desplazándose la misma cantidad."
L["Show while this condition is false"] = "Mostrar mientras esta condición sea falsa"
L["Show who each spell is being cast on, exactly like the nameplate cast bars."] = "Muestra a quién se le está lanzando cada hechizo, igual que las barras de lanzamiento de las placas de nombre."
L["Show who the spell is being cast on, exactly like the nameplate cast bars."] = "Muestra a quién se le está lanzando el hechizo, igual que las barras de lanzamiento de las placas de nombre."
L["Show world latency instead of home latency."] = "Muestra la latencia mundial en lugar de la latencia local."
L["Show your own class buffs on every spec, not only on the tracked healer spec."] = "Muestra los beneficios de tu propia clase en todas las especializaciones, no solo en la especialización de sanador seguida."
L["Show/Hide Hitbox Overlay"] = "Mostrar/ocultar superposición de zona de impacto" -- TODO: confirmar termo oficial
L["Show/Hide Windows Keybind"] = "Mostrar/ocultar tecla de acceso rápido de ventanas"
L["Show/Hide on Preview"] = "Mostrar/ocultar en la vista previa"
L["Showing the '%s' override's value. Edit it from that override's editing mode."] = "Se está mostrando el valor de la anulación '%s'. Edítalo desde el modo de edición de esa anulación."
L["Showing this aura from any caster; click for your casts only."] = "Mostrando esta aura de cualquier lanzador; haz clic para solo tus lanzamientos."
L["Showing this aura from your casts only; click for any caster."] = "Mostrando esta aura solo de tus lanzamientos; haz clic para cualquier lanzador."
L["Shown"] = "Mostrado"
L["Shown At Cursor"] = "Mostrado en el cursor"
L["Shown on Modifier"] = "Mostrado con modificador"
L["Shows Blizzard's default icon slot background texture behind empty action bar slots."] = "Muestra la textura de fondo predeterminada de Blizzard para ranuras de icono detrás de las ranuras vacías de la barra de acción."
L["Shows Sweeping Strikes charges on the resource bar; Unit Frames and the personal Nameplate show them regardless."] = "Muestra las cargas de Golpes amplios en la barra de recurso; los Marcos de unidad y la Placa de nombre personal las muestran de todos modos." -- TODO: confirmar termo oficial
L["Shows a bar that fills over the global cooldown."] = "Muestra una barra que se rellena durante el tiempo de reutilización global."
L["Shows a clickable list of online friends and guildmates in the Social and Guild button tooltips."] = "Muestra una lista en la que se puede hacer clic de amigos y compañeros de hermandad conectados en los tooltips de los botones Social y Hermandad."
L["Shows a colored overlay at the end of the cast bar representing your network latency for each spell. Helps you time spell queuing."] = "Muestra una superposición de color al final de la barra de lanzamiento que representa tu latencia de red para cada hechizo. Te ayuda a calcular el momento de encolar hechizos."
L["Shows a countdown bar below the queue accept popup indicating how long you have to accept. Works with or without the reskin. Use the swatch and cog to set the countdown text color, text size, bar height and text offset."] = "Muestra una barra de cuenta atrás debajo de la ventana emergente de aceptación de cola que indica cuánto tiempo tienes para aceptar. Funciona con o sin el rediseño. Usa la muestra y el engranaje para definir el color del texto de la cuenta atrás, el tamaño del texto, la altura de la barra y el desplazamiento del texto."
L["Shows a countdown bar below the queue accept popup indicating how long you have to accept. Works with or without the reskin. Use the swatch and cog to set the countdown text color, text size. bar height and text offset."] = "Muestra una barra de cuenta atrás debajo de la ventana emergente de aceptación de cola que indica cuánto tiempo tienes para aceptar. Funciona con o sin el rediseño. Usa la muestra y el engranaje para definir el color del texto de la cuenta atrás, el tamaño del texto, la altura de la barra y el desplazamiento del texto."
L["Shows a countdown to the Arcane Soul window over the last seconds of Arcane Surge, then the time left inside it. Sunfury Arcane Mages only."] = "Muestra una cuenta atrás hasta la ventana de Alma arcana durante los últimos segundos de Aumento arcano, y luego el tiempo restante dentro de ella. Solo para Magos arcanos de Furia solar." -- TODO: confirmar termo oficial (Sunfury, Arcane Surge)
L["Shows a faint white wash over each block on mouseover."] = "Muestra un ligero tinte blanco sobre cada bloque al pasar el ratón."
L["Shows a house or globe icon marking which latency each value is."] = "Muestra un icono de casa o de globo terráqueo que indica a qué latencia corresponde cada valor."
L["Shows a large on-screen alert (e.g. \"Player DIED!\") whenever a party or raid member dies, so you immediately notice deaths during dungeons and raids. Use Unlock Mode to reposition the alert."] = "Muestra una alerta grande en pantalla (p. ej. \"¡El jugador MURIÓ!\") cada vez que muere un miembro del grupo o banda, para que notes las muertes al instante durante mazmorras y bandas. Usa el Modo de desbloqueo para reposicionar la alerta."
L["Shows a large on-screen text when you enter and/or leave combat (e.g. \"+Combat\" / \"-Combat\"). Use the cog to set the display text, size, colors and which transitions are shown; use Unlock Mode to reposition the alert."] = "Muestra un texto grande en pantalla cuando entras y/o sales de combate (p. ej. \"+Combate\" / \"-Combate\"). Usa el engranaje para definir el texto mostrado, el tamaño, los colores y qué transiciones se muestran; usa el Modo de desbloqueo para reposicionar la alerta."
L["Shows a mana percentage row for every healer in your group as its own movable text display. Position it in Unlock Mode."] = "Muestra una fila de porcentaje de maná para cada sanador de tu grupo como su propia visualización de texto movible. Colócala en el Modo de desbloqueo."
L["Shows a map icon of the friend's region if they are not playing within your region"] = "Muestra un icono de mapa de la región del amigo si no está jugando dentro de tu región"
L["Shows a movable strip of recent spell icons. Shift-drag to reposition."] = "Muestra una tira movible de iconos de hechizos recientes. Mantén pulsado Mayús y arrastra para reposicionarla."
L["Shows a player's RP title on their unit tooltip."] = "Muestra el título de rol de un jugador en su tooltip de unidad."
L["Shows a popup with party and guild keystones when typing /keys."] = "Muestra una ventana emergente con las llaves de grupo y hermandad al escribir /keys."
L["Shows a rest icon while your character is resting."] = "Muestra un icono de descanso mientras tu personaje está descansando."
L["Shows a single Blood Plague debuff on enemy nameplates instead of one per copy (Blood Boil from weapon copies)."] = "Muestra un único perjuicio de Peste de sangre en las placas de nombre enemigas en lugar de uno por copia (Ebullición de sangre de copias de arma)." -- TODO: confirmar termo oficial (Blood Plague, Blood Boil)
L["Shows a small white tick mark on the cast bar at the point where the cast will be when your interrupt comes off cooldown."] = "Muestra una pequeña marca blanca en la barra de lanzamiento en el punto donde estará el lanzamiento cuando tu interrupción salga del tiempo de reutilización."
L["Shows a small white tick mark where the cast will be when your interrupt comes off cooldown."] = "Muestra una pequeña marca blanca en el punto donde estará el lanzamiento cuando tu interrupción salga del tiempo de reutilización."
L["Shows a special color for nameplates that another tank in your raid has aggro on."] = "Muestra un color especial en las placas de nombre sobre las que otro tanque de tu banda tiene aggro." -- JARGAO (Aggro)
L["Shows a special color for non caster/mini-boss enemies when you do not have aggro on them."] = "Muestra un color especial para enemigos que no son lanzadores/minijefes cuando no tienes aggro sobre ellos." -- JARGAO (Aggro)
L["Shows a special color for non caster/mini-boss enemies when you have aggro on them."] = "Muestra un color especial para enemigos que no son lanzadores/minijefes cuando tienes aggro sobre ellos." -- JARGAO (Aggro)

-- == Batch 53 (missing_esES.txt): Shows a standalone window with spell cast history as bars...Spell  ====
L["Shows a standalone window with spell cast history as bars. Matches your Damage Meters styling."] = "Muestra una ventana independiente con el historial de lanzamientos como barras. Coincide con el estilo de tus Medidores de daño."
L["Shows an envelope icon when you have unread mail."] = "Muestra un icono de sobre cuando tienes correo sin leer."
L["Shows any debuff with a dispel type (Magic, Curse, Disease, Poison, Bleed), even if you cannot remove it"] = "Muestra cualquier perjuicio con un tipo de disipación (Magia, Maldición, Enfermedad, Veneno, Sangrado), incluso si no puedes eliminarlo"
L["Shows each crest's icon in front of its amount."] = "Muestra el icono de cada cresta delante de su cantidad."
L["Shows each healer's name before the number while in a raid. In a party the display always shows numbers only."] = "Muestra el nombre de cada sanador antes del número mientras estás en una banda. En un grupo, la visualización siempre muestra solo números."
L["Shows elapsed / total duration (e.g. 0.4 / 2.0) instead of counting down from the total."] = "Muestra la duración transcurrida / total (p. ej. 0.4 / 2.0) en lugar de la cuenta atrás desde el total."
L["Shows every debuff except the ones you or your pet apply"] = "Muestra todos los perjuicios excepto los que aplicas tú o tu mascota"
L["Shows every debuff on this frame."] = "Muestra todos los perjuicios en este marco."
L["Shows external defensives cast on you (Pain Suppression, Ironbark, etc.) in its own movable frame; position it via Unlock Mode."] = "Muestra los defensivos externos lanzados sobre ti (Supresión del dolor, Corteza de hierro, etc.) en su propio marco movible; posiciónalo mediante el Modo de desbloqueo."
L["Shows full spell and ability descriptions in tooltips instead of just the name. Only enforced on login after you toggle this setting."] = "Muestra las descripciones completas de hechizos y habilidades en los tooltips en lugar de solo el nombre. Solo se aplica al iniciar sesión después de cambiar este ajuste."
L["Shows item level and secondary stats in the Character button's tooltip."] = "Muestra el nivel de objeto y las estadísticas secundarias en el tooltip del botón de Personaje."
L["Shows large amounts using K/M suffixes (284,208g becomes 284.2Kg) instead of the full grouped number. The tooltip always shows the exact amount."] = "Muestra las cantidades grandes usando sufijos K/M (284.208po se convierte en 284,2Kpo) en lugar del número completo agrupado. El tooltip siempre muestra la cantidad exacta."
L["Shows only auras flagged for raid frames during combat"] = "Muestra solo las auras marcadas para los Marcos de banda durante el combate"
L["Shows only auras with a dispel type you can dispel"] = "Muestra solo las auras con un tipo de disipación que puedes disipar"
L["Shows only buffs that can be canceled"] = "Muestra solo los beneficios que se pueden cancelar"
L["Shows only buffs you can spellsteal or purge"] = "Muestra solo los beneficios que puedes robar o purgar"
L["Shows only crowd-control auras"] = "Muestra solo las auras de control de masas"
L["Shows only debuffs Blizzard flags as important"] = "Muestra solo los perjuicios que Blizzard marca como importantes"
L["Shows only debuffs Blizzard flags as important."] = "Muestra solo los perjuicios que Blizzard marca como importantes."
L["Shows only debuffs applied by bosses"] = "Muestra solo los perjuicios aplicados por jefes"
L["Shows only debuffs flagged for your role"] = "Muestra solo los perjuicios marcados para tu rol"
L["Shows only debuffs from Blizzard's curated raid-frame debuff set"] = "Muestra solo los perjuicios del conjunto de perjuicios de Marcos de banda seleccionado por Blizzard"
L["Shows only debuffs not caused by any player or player pet (this is what shows most pve debuffs, do not check this while All Debuffs is selected!"] = "Muestra solo los perjuicios no causados por ningún jugador ni mascota de jugador (esto es lo que muestra la mayoría de los perjuicios de PvE; ¡no marques esto mientras Todos los perjuicios esté seleccionado!"
L["Shows only external defensive cooldowns cast on the unit"] = "Muestra solo los tiempos de reutilización defensivos externos lanzados sobre la unidad"
L["Shows only major defensive cooldowns"] = "Muestra solo los tiempos de reutilización defensivos principales"
L["Shows only priority debuffs"] = "Muestra solo los perjuicios prioritarios"
L["Shows only the Buffs that appear on Raid Frames"] = "Muestra solo los Beneficios que aparecen en los Marcos de banda"
L["Shows only the Buffs you apply"] = "Muestra solo los Beneficios que aplicas"
L["Shows only the Buffs/Debuffs that appear on Raid Frames"] = "Muestra solo los Beneficios/Perjuicios que aparecen en los Marcos de banda"
L["Shows only the Buffs/Debuffs you apply"] = "Muestra solo los Beneficios/Perjuicios que aplicas"
L["Shows only the Debuffs that appear on Raid Frames"] = "Muestra solo los Perjuicios que aparecen en los Marcos de banda"
L["Shows only the Debuffs you apply"] = "Muestra solo los Perjuicios que aplicas"
L["Shows only the buffs you apply"] = "Muestra solo los beneficios que aplicas"
L["Shows only the debuffs you apply that Blizzard also flags as important."] = "Muestra solo los perjuicios que aplicas y que Blizzard también marca como importantes."
L["Shows only the debuffs you apply."] = "Muestra solo los perjuicios que aplicas."
L["Shows only the spells Blizzard flags as Important"] = "Muestra solo los hechizos que Blizzard marca como importantes"
L["Shows only the stricter in-combat subset of the raid set"] = "Muestra solo el subconjunto más estricto en combate del conjunto de banda"
L["Shows only this frame's Tracked Auras; add them with Edit Tracked Auras at the top of this menu."] = "Muestra solo las Auras seguidas de este marco; añádelas con Editar auras seguidas en la parte superior de este menú."
L["Shows saved instance lockouts with boss kill progress on the minimap calendar button tooltip."] = "Muestra los bloqueos de instancia guardados con el progreso de jefes derrotados en el tooltip del botón de calendario del minimapa."
L["Shows silver and copper, not just gold."] = "Muestra la plata y el cobre, no solo el oro."
L["Shows start as a small icon, and the keybind switches between the icon and the full windows. Turn off to show full windows and make the keybind hide and show them."] = "Al iniciar se muestra como un pequeño icono, y el atajo de teclado alterna entre el icono y las ventanas completas. Desactívalo para mostrar las ventanas completas y hacer que el atajo de teclado las oculte y las muestre."
L["Shows the 'Disable Feature' text below the teleport button. When off, the text is hidden and the window is 20px shorter."] = "Muestra el texto 'Desactivar función' debajo del botón de teletransporte. Cuando está desactivado, el texto se oculta y la ventana es 20px más corta."
L["Shows the Convert to Raid button, which reads Convert to Party while you are in a raid."] = "Muestra el botón Convertir en banda, que aparece como Convertir en grupo mientras estás en una banda."
L["Shows the Disband button. It always asks before disbanding, but hiding it puts it out of misclick range for good."] = "Muestra el botón Disolver. Siempre pide confirmación antes de disolver, pero ocultarlo lo deja definitivamente fuera del alcance de un clic accidental."
L["Shows the Role Check button in window layouts and enables Right Click: Role Check on Compact Band."] = "Muestra el botón Comprobación de rol en las disposiciones de ventana y activa Clic derecho: Comprobación de rol en Banda compacta."
L["Shows the Role Check button. Turn it off and the remaining buttons close the gap."] = "Muestra el botón Comprobación de rol. Desactívalo y los botones restantes cierran el hueco."
L["Shows the active talent loadout name."] = "Muestra el nombre de la configuración de talentos activa."
L["Shows the approximate distance to your current target as movable on-screen text (default 30-35). Use the cog for format, alignment, and text size; use Unlock Mode to position or Anchor to your Player Frame."] = "Muestra la distancia aproximada a tu objetivo actual como texto movible en pantalla (predeterminado 30-35). Usa el engranaje para el formato, la alineación y el tamaño del texto; usa el Modo de desbloqueo para posicionarlo o Anclar a tu marco de Jugador."
L["Shows the approximate distance to your current target on its nameplate as a range bracket, e.g. 15+ when the target is 15-20 yards away."] = "Muestra la distancia aproximada a tu objetivo actual en su placa de nombre como un rango, p. ej. 15+ cuando el objetivo está a 15-20 metros."
L["Shows the audio icon next to the volume bar."] = "Muestra el icono de audio junto a la barra de volumen."
L["Shows the checked classes' mobility spell(s) counting down on cooldown. Nothing checked = feature disabled. Use Unlock Mode to reposition/resize."] = "Muestra la cuenta atrás del tiempo de reutilización de los hechizos de movilidad de las clases marcadas. Nada marcado = función desactivada. Usa el Modo de desbloqueo para reposicionar/redimensionar."
L["Shows the coin icon next to the amount."] = "Muestra el icono de moneda junto a la cantidad."
L["Shows the combat status text only while your character is in combat."] = "Muestra el texto de estado de combate solo mientras tu personaje está en combate."
L["Shows the consumable rank (quality) diamond icon on action buttons."] = "Muestra el icono de diamante de rango (calidad) del consumible en los botones de acción."
L["Shows the currency icon next to the amount."] = "Muestra el icono de la divisa junto a la cantidad."
L["Shows the currency's description text in the tooltip. Turn off for a compact tooltip with just the name and the amount."] = "Muestra el texto de descripción de la divisa en el tooltip. Desactívalo para un tooltip compacto con solo el nombre y la cantidad."
L["Shows the debuff's dispel type icon (Magic, Curse, Disease, Poison, Bleed) on the bar."] = "Muestra el icono de tipo de disipación del perjuicio (Magia, Maldición, Enfermedad, Veneno, Sangrado) en la barra."
L["Shows the debuffs you apply plus important debuffs from anyone."] = "Muestra los perjuicios que aplicas más los perjuicios importantes de cualquiera."
L["Shows the default Friends section for friends not in a custom group."] = "Muestra la sección de Amigos predeterminada para los amigos que no están en un grupo personalizado."
L["Shows the focus target's raid marker icon next to the cast bar itself, instead of (or in addition to) the frame-level marker in Extras."] = "Muestra el icono de marcador de banda del objetivo de foco junto a la propia barra de lanzamiento, en lugar de (o además de) el marcador a nivel de marco en Extras."
L["Shows the icon next to the durability readout."] = "Muestra el icono junto a la lectura de durabilidad."
L["Shows the item level on each item in the character sheet gear flyout (the popup of same-slot bag items that appears when hovering an equipped slot), coloured by quality."] = "Muestra el nivel de objeto en cada objeto del menú desplegable de equipo de la ficha de personaje (la ventana emergente de objetos de bolsa de la misma ranura que aparece al pasar el ratón sobre una ranura equipada), coloreado según la calidad."
L["Shows the item level on weapons and armor a vendor sells."] = "Muestra el nivel de objeto en las armas y armaduras que vende un vendedor."
L["Shows the items as a list instead of pages."] = "Muestra los objetos como una lista en lugar de páginas."
L["Shows the map pin next to the zone name."] = "Muestra el marcador de mapa junto al nombre de la zona."
L["Shows the marker icon next to the coordinates."] = "Muestra el icono de marcador junto a las coordenadas."
L["Shows the nameplate-style dragon badge on elite, rare elite, and rare targets."] = "Muestra la insignia de dragón de estilo placa de nombre en objetivos élite, élite raro y raro."
L["Shows the online friend and guild counters."] = "Muestra los contadores de amigos y hermandad conectados."
L["Shows the overlay only for debuffs you can currently dispel."] = "Muestra la superposición solo para los perjuicios que puedes disipar actualmente."
L["Shows the ping mark on a member's frame when someone pings them (needs Blizzard's Show Pings on Raid Frames setting on)."] = "Muestra la marca de ping en el marco de un miembro cuando alguien le hace ping (requiere que el ajuste de Blizzard Mostrar pings en los marcos de banda esté activado)."
L["Shows the plugin's own icon next to its text."] = "Muestra el icono propio del complemento junto a su texto."
L["Shows the plugin's text. Off leaves an icon-only block that still carries the plugin's tooltip and clicks."] = "Muestra el texto del complemento. Desactivado deja un bloque solo con icono que sigue teniendo el tooltip y los clics del complemento."
L["Shows the profession icons next to the text."] = "Muestra los iconos de profesión junto al texto."
L["Shows the raid target marker icon on boss frames."] = "Muestra el icono de marcador de objetivo de banda en los Marcos de jefe."
L["Shows the rotation-helper ring on the button holding the One Button Assist action."] = "Muestra el anillo de ayuda de rotación en el botón que contiene la acción Asistencia de un botón."
L["Shows the spec icon next to the text."] = "Muestra el icono de especialización junto al texto."
L["Shows the target marker directly before the enemy name text. Uses its own size and does not use the Core Positions raid marker slot."] = "Muestra el marcador de objetivo justo antes del texto del nombre del enemigo. Usa su propio tamaño y no usa la ranura de marcador de banda de Posiciones básicas."
L["Shows the window even when you can do nothing about what it reports. Every column is read from your own client, so this view is complete rather than degraded."] = "Muestra la ventana incluso cuando no puedes hacer nada sobre lo que informa. Cada columna se lee desde tu propio cliente, por lo que esta vista es completa en lugar de degradada."
L["Shows the zone and the subzone together instead of the subzone alone."] = "Muestra la zona y la subzona juntas en lugar de solo la subzona."
L["Shows tick marks on channeled spells. Only supported spells are shown, request missing spells on Discord."] = "Muestra marcas en los hechizos canalizados. Solo se muestran los hechizos compatibles; solicita los hechizos que falten en Discord."
L["Shows where your interrupt will be ready during a cast. \"Tick\" marks the exact spot on the cast bar; \"Tick + Bar\" also colours the window during which your interrupt will be available."] = "Muestra dónde estará lista tu interrupción durante un lanzamiento. \"Marca\" señala el punto exacto en la barra de lanzamiento; \"Marca + Barra\" también colorea la ventana durante la cual tu interrupción estará disponible."
L["Shows where your interrupt will be ready during an enemy cast. \"Tick\" marks the exact spot on the cast bar; \"Tick + Bar\" also colours the window during which your interrupt will be available."] = "Muestra dónde estará lista tu interrupción durante el lanzamiento de un enemigo. \"Marca\" señala el punto exacto en la barra de lanzamiento; \"Marca + Barra\" también colorea la ventana durante la cual tu interrupción estará disponible."
L["Shows your best split on upcoming bosses instead of only killed ones."] = "Muestra tu mejor división en los próximos jefes en lugar de solo los derrotados."
L["Shows your free bag slots."] = "Muestra tus ranuras de bolsa libres."
