L["Smallest on-screen size a reskinned bar is drawn at.\n\nWidget bars on a nameplate inherit that nameplate's scale, so they come out tiny on small units. Below this size the bar is scaled up instead, text and all.\n\nSet to 0 to mirror Blizzard's size exactly."] = "Tamaño mínimo en pantalla con el que se dibuja una barra rediseñada.\n\nLas barras de widget en una placa de nombre heredan la escala de esa placa, por lo que salen diminutas en unidades pequeñas. Por debajo de este tamaño, la barra se escala hacia arriba en su lugar, texto incluido.\n\nEstablece 0 para igualar exactamente el tamaño de Blizzard."
