L["Sorting normally packs your items into the first free slots, at the top of the grid. Turn this on to pack them into the last slots instead, so the empty slots end up at the top. The item order itself does not change. This affects the OneBag, MultiBag and bank views -- category views fill their own grid with no gaps, so there is nothing to move. MultiBag and the bank use Blizzard's own sorting, so while this is on it also flips Blizzard's cleanup direction; turning it back off restores the direction you had."] = "La ordenación normalmente agrupa tus objetos en las primeras ranuras libres, en la parte superior de la cuadrícula. Activa esto para agruparlos en las últimas ranuras en su lugar, de modo que las ranuras vacías acaben arriba. El orden de los objetos en sí no cambia. Esto afecta a las vistas de Bolsa única, Multibolsa y banco -- las vistas por categoría llenan su propia cuadrícula sin huecos, así que no hay nada que mover. Multibolsa y el banco usan la ordenación propia de Blizzard, por lo que mientras esto esté activado también invierte la dirección de limpieza de Blizzard; desactivarlo de nuevo restaura la dirección que tenías."
