L["Split items by category -- Armor, Consumables, Professions and so on -- using the same category list, order and renames as the All Items bag view. Nests inside the expansion headers when Nest by Expansion is also on. Categories that split further do so automatically: gear by equipment slot, Professions and Trade Goods by profession and material type."] = "Divide los objetos por categoría -- Armadura, Consumibles, Profesiones, etc. -- usando la misma lista de categorías, orden y renombrados que la vista de bolsa Todos los objetos. Se anida dentro de los encabezados de expansión cuando Anidar por expansión también está activado. Las categorías que se dividen más lo hacen automáticamente: el equipo por ranura de equipamiento, y Profesiones y Bienes comerciales por profesión y tipo de material."
