L["Suppresses right click targeting. Enemies applies everywhere. Allies In Combat only suppresses friendly targets while you are in combat, so you can still right click vendors and NPCs out of combat.\n\nNote: while this is active, holding Left+Right click to move forward won't work if your cursor is over a suppressed nameplate/unit, since this feature has to take over the right mouse button entirely to block targeting."] = "Suprime el objetivo por clic derecho. Enemigos se aplica en todas partes. Aliados en combate solo suprime los objetivos amistosos mientras estás en combate, para que aún puedas hacer clic derecho en vendedores y PNJ fuera de combate.\n\nNota: mientras esto está activo, mantener pulsado clic Izquierdo+Derecho para avanzar no funcionará si tu cursor está sobre una placa de nombre/unidad suprimida, ya que esta función tiene que tomar el control completo del botón derecho del ratón para bloquear el objetivo."
