L["Thank you for helping test EllesmereUI during beta! During testing, many systemic changes were made to build the foundation for a stable, flexible addon going forward.\n\nTo ensure a clean experience for everyone, all settings have been automatically reset. You will need to reconfigure your UI. We apologize for the inconvenience, and appreciate your patience.\n\nPrevious profile exports are no longer compatible and will need to be re-created."] = "¡Gracias por ayudar a probar EllesmereUI durante la beta! Durante las pruebas se hicieron muchos cambios sistémicos para construir la base de un addon estable y flexible de cara al futuro.\n\nPara garantizar una experiencia limpia para todos, todos los ajustes se han restablecido automáticamente. Tendrás que reconfigurar tu interfaz. Disculpa las molestias, y gracias por tu paciencia.\n\nLas exportaciones de perfil anteriores ya no son compatibles y habrá que volver a crearlas."
L["Thank you for making EllesmereUI possible."] = "Gracias por hacer posible EllesmereUI."
L["Thank you to all who support EllesmereUI and its incredible support team!"] = "Gracias a todos los que apoyan a EllesmereUI y a su increíble equipo de soporte."
L["That setting is stored by list position and can't be safely overridden."] = "Ese ajuste se guarda por posición en la lista y no se puede anular de forma segura."
L["The \"You received\" popups for loot, currency, and upgrades."] = "Las ventanas emergentes \"Has recibido\" de botín, divisa y mejoras."
L["The \"you have been invited to a group\" dialogs, with your role and Accept / Decline."] = "Los diálogos de \"has sido invitado a un grupo\", con tu rol y Aceptar / Rechazar."
L["The Armory"] = "La Armería"
L["The Armory (%d)"] = "La Armería (%d)"
L["The Battle.net friend online and offline toast gets a window skin, with its own Friend Notifications card"] = "El aviso de amigo de Battle.net conectado y desconectado recibe una skin de ventana, con su propia tarjeta de Notificaciones de amigos"
L["The Battle.net popup when a friend comes online or goes offline, plus broadcasts and invites."] = "La ventana emergente de Battle.net cuando un amigo se conecta o desconecta, además de mensajes de difusión e invitaciones."
L["The Blinding Vale"] = "El Valle Deslumbrante" -- TODO: confirmar termo oficial
L["The Combat Indicator is not available for the Focus frame."] = "El Indicador de combate no está disponible para el marco de Foco."
L["The Cooldown Manager can do far more than show cooldowns, it also has per-spell settings, bar glows, tracking bars and more! Check out some tips and tricks for getting more from it."] = "¡El Gestor de tiempos de reutilización puede hacer mucho más que mostrar tiempos de reutilización; también tiene ajustes por hechizo, resplandores de barra, barras de seguimiento y más! Descubre algunos consejos y trucos para sacarle más partido."
