L["The LFG Reminder popup now matches dungeon names on every client language, not only English and Russian."] = "La ventana emergente del Recordatorio de LFG ahora coincide con los nombres de mazmorra en todos los idiomas de cliente, no solo inglés y ruso."
L["The Missing Pet reminder no longer appears while mounted or flashes on dismount."] = "El recordatorio de Mascota ausente ya no aparece mientras estás montado ni parpadea al desmontar."
L["The NPC dialog window: greeting text, gossip and quest options, and goodbye button."] = "La ventana de diálogo de PNJ: texto de saludo, opciones de cotilleo y misión, y botón de despedida."
L["The NPC quest window: quest detail, progress, and reward panels plus the multi-quest greeting list."] = "La ventana de misión de PNJ: paneles de detalle, progreso y recompensa de la misión, además de la lista de saludo de misiones múltiples."
L["The Pet Bar cannot use group-based visibility."] = "La Barra de mascota no puede usar visibilidad basada en grupo."
L["The Player Spells window: talents, spec selection, and the spellbook."] = "La ventana de Hechizos de jugador: talentos, selección de especialización y el libro de hechizos."
L["The Ring of Valor"] = "El Anillo del Valor" -- TODO: confirmar termo oficial
L["The Rookery"] = "El Nidal" -- TODO: confirmar termo oficial
L["The Social window frame, border, title bar, Battle.net bar, search boxes, filter dropdowns and buttons. List contents and the side tab icons stay untouched."] = "El marco, borde, barra de título, barra de Battle.net, cuadros de búsqueda, menús desplegables de filtro y botones de la ventana Social. El contenido de las listas y los iconos de las pestañas laterales quedan intactos."
L["The Venomous Abyss"] = "El Abismo Venenoso" -- TODO: confirmar termo oficial
L["The Voidspire"] = "La Aguja del Vacío" -- TODO: confirmar termo oficial
L["The Voidspire (Raid)"] = "La Aguja del Vacío (Banda)" -- TODO: confirmar termo oficial
L["The Whirlwind and Sweeping Strikes bar honors the Empty Bar Overlay again so spent charges show in Dark Mode, no longer draws a second set of divider lines with Bar Spacing set, hides its threshold strip while thresholds are disabled, and accepts a stack threshold up to 20."] = "La barra de Torbellino y Golpes amplios vuelve a respetar la Superposición de barra vacía para que las cargas gastadas se muestren en el Modo oscuro, ya no dibuja un segundo conjunto de líneas divisorias cuando hay Espaciado de barra definido, oculta su franja de umbral mientras los umbrales están desactivados, y acepta un umbral de pila de hasta 20." -- TODO: confirmar termo oficial
L["The achievement window: categories, rows, progress bars, and search."] = "La ventana de logros: categorías, filas, barras de progreso y búsqueda."
L["The active override's Buff Manager is bound to the open page. Leave the Buff Manager tab to switch overrides."] = "El Gestor de beneficios de la anulación activa está vinculado a la página abierta. Sal de la pestaña del Gestor de beneficios para cambiar de anulación."
L["The active override's custom %s is bound to this page. Leave the %s tab to switch to another override."] = "El %s personalizado de la anulación activa está vinculado a esta página. Sal de la pestaña %s para cambiar a otra anulación."
L["The active override's custom Buff Manager is bound to this page. Leave the Buff Manager tab to switch to another override."] = "El Gestor de beneficios personalizado de la anulación activa está vinculado a esta página. Sal de la pestaña del Gestor de beneficios para cambiar a otra anulación."
L["The addon manager: list rows, checkboxes, and buttons."] = "El gestor de addons: filas de lista, casillas de verificación y botones."
L["The amount of damage you can take"] = "La cantidad de daño que puedes recibir"
L["The auction house: browse, sell, and my auctions views."] = "La casa de subastas: vistas de explorar, vender y mis subastas."
L["The background colour behind Dark Mode bars (Unit Frames, Raid Frames, Resource Bars)."] = "El color de fondo detrás de las barras del Modo oscuro (Marcos de unidad, Marcos de banda, Barras de recurso)."
L["The bank window catches up to the bags: nest OneBank and OneWarbank by expansion, group items by your bag categories with automatic splits by equipment slot, profession and material, and browse a category sidebar that spans your character bank and warband together."] = "La ventana de banco se pone al día con las bolsas: anida Banco único y Banco de hueste único por expansión, agrupa los objetos según tus categorías de bolsa con divisiones automáticas por ranura de equipamiento, profesión y material, y navega por una barra lateral de categorías que abarca a la vez tu banco de personaje y el de hueste."
L["The class and profession trainer window: skill list, train button, and cost display."] = "La ventana de entrenador de clase y profesión: lista de habilidades, botón de entrenar y visualización del coste."
L["The class resource bar gains a spec picker to choose which specs show it, matching the power and health bars."] = "La barra de recurso de clase obtiene un selector de especialización para elegir en qué especializaciones se muestra, igual que las barras de poder y vida."
L["The customer crafting orders window: browse, order form, and my orders."] = "La ventana de pedidos de fabricación de clientes: explorar, formulario de pedido y mis pedidos."
L["The damage and tank cut of Light of Nitex. The same style refocused on your rotation, procs, and cooldowns front and center."] = "La versión de daño y tanque de Luz de Nitex. El mismo estilo reenfocado en tu rotación, procs y tiempos de reutilización en primer plano y al centro."
L["The damage dealer cut of Midnight Lily. A focused, low-clutter layout that keeps your rotation and cooldowns front and center."] = "La versión de daño de Lirio de Medianoche. Una disposición enfocada y despejada que mantiene tu rotación y tiempos de reutilización en primer plano y al centro."
L["The dark counterpart to Lazar's Dawn. A moody, high-contrast layout that keeps focus locked on the fight."] = "La contraparte oscura de Amanecer de Lazar. Una disposición sombría y de alto contraste que mantiene el foco fijo en el combate."
L["The default EllesmereUI look"] = "El aspecto predeterminado de EllesmereUI"
L["The delve difficulty window: tier dropdown, reward list and Enter button. The Map Properties row is left stock -- it is a Blizzard widget display and is not safe to restyle."] = "La ventana de dificultad de incursión en solitario: menú desplegable de nivel, lista de recompensas y botón de entrar. La fila de Propiedades del mapa se deja sin modificar -- es una visualización de widget de Blizzard y no es seguro reestilizarla."
L["The dispel type icon gains an Icon Size slider in its cog menu so you can make it larger or smaller."] = "El icono de tipo de disipación obtiene un control deslizante de Tamaño de icono en su menú de engranaje para que puedas hacerlo más grande o más pequeño."
L["The display language for the EllesmereUI options panel. Auto follows your game client. Untranslated text falls back to English."] = "El idioma de visualización del panel de opciones de EllesmereUI. Automático sigue a tu cliente del juego. El texto sin traducir vuelve al inglés."
L["The exact inverse of Skyriding (Airborne): anything that is not airborne on a glide-capable mount or flight form, standing on the ground included."] = "El inverso exacto de Vuelo aéreo (en el aire): cualquier cosa que no esté en el aire con una montura capaz de planear o una forma de vuelo, incluido estar de pie en el suelo."
L["The flat fill colour bars use when Dark Mode is enabled (Unit Frames, Raid Frames, Resource Bars)."] = "El color de relleno plano que usan las barras cuando el Modo oscuro está activado (Marcos de unidad, Marcos de banda, Barras de recurso)."
L["The gap between a nested menu's icons and the entry that opens it."] = "El hueco entre los iconos de un menú anidado y la entrada que lo abre."
L["The gem socketing window with squared gem slots."] = "La ventana de engaste de gemas con ranuras de gema cuadradas."
L["The highlight overlay that appears on a spell button while it is the active/current action. Disable to hide it."] = "La superposición de resaltado que aparece en un botón de hechizo mientras es la acción activa/actual. Desactívala para ocultarla."
L["The housing dashboard window background, border, and title bar."] = "El fondo, borde y barra de título de la ventana del panel de vivienda."
L["The interrupt flash now clears the instant a target dies, so the cast bar no longer looks squished by the death animation."] = "El destello de interrupción ahora se borra en el instante en que un objetivo muere, para que la barra de lanzamiento ya no se vea aplastada por la animación de muerte."
L["The item conversion window (catalyst and similar kiosks)."] = "La ventana de conversión de objetos (catalizador y quioscos similares)."
L["The item preview / transmog dressing room window."] = "La ventana de vista previa de objeto / vestidor de transfiguración."
L["The item upgrade window: upgrade slot, track selector, cost, and the currency strip."] = "La ventana de mejora de objeto: ranura de mejora, selector de vía, coste y la franja de divisa."
L["The loot window: item rows with squared icons, kept item quality colors."] = "La ventana de botín: filas de objeto con iconos cuadrados, se mantienen los colores de calidad de objeto."
L["The macro editor: tabs, icon grid, text well, and buttons."] = "El editor de macros: pestañas, cuadrícula de iconos, campo de texto y botones."
L["The mailbox: inbox rows, send mail, open mail, and attachment slots."] = "El buzón: filas de bandeja de entrada, enviar correo, abrir correo y ranuras de adjuntos."
L["The monthly calendar grid, event dialogs, and navigation arrows."] = "La cuadrícula del calendario mensual, los diálogos de evento y las flechas de navegación."
L["The most cast bars shown at once. Extra casters take a bar as soon as one frees up."] = "El número máximo de barras de lanzamiento mostradas a la vez. Los lanzadores adicionales ocupan una barra en cuanto se libera una."
L["The need / greed / pass roll popups, with a squared icon and a flat roll timer."] = "Las ventanas emergentes de tirada de necesidad / codicia / pasar, con un icono cuadrado y un temporizador de tirada plano."
L["The overlay that appears on the icon when you hover your mouse over a spell button"] = "La superposición que aparece en el icono cuando pasas el ratón sobre un botón de hechizo"
L["The overlay that appears on the icon when you press and hold a spell button"] = "La superposición que aparece en el icono cuando mantienes pulsado un botón de hechizo"
L["The override group '%s' already provides the custom unlock mode for your current spec. Customize it there, or remove this spec from that group."] = "El grupo de anulación '%s' ya proporciona el modo de desbloqueo personalizado para tu especialización actual. Personalízalo allí, o elimina esta especialización de ese grupo."
L["The panel the minimap Group Finder eye shows on hover: queue titles, role icons and counts, and time in queue."] = "El panel que muestra el ojo del Buscador de grupo del minimapa al pasar el ratón: títulos de cola, iconos y recuentos de rol, y tiempo en cola."
L["The pasted string could not be read completely. Please paste it again."] = "La cadena pegada no se pudo leer por completo. Vuelve a pegarla."
L["The pending-rolls window: encounter picker, roll timer, and the result rows."] = "La ventana de tiradas pendientes: selector de encuentro, temporizador de tirada y las filas de resultado."
L["The pet frame updates its name and portrait when you swap pets (for example Voidwalker to Felhunter)."] = "El marco de mascota actualiza su nombre y retrato cuando cambias de mascota (por ejemplo, de Caminante del vacío a Cazador infernal)."
L["The player-to-player trade window: frame, both item columns, the enchant slots, money rows and buttons. Item icons are squared and carry a rarity border. Both portraits are removed, as on every other window."] = "La ventana de comercio entre jugadores: marco, ambas columnas de objetos, las ranuras de encantamiento, filas de dinero y botones. Los iconos de objeto son cuadrados y llevan un borde de rareza. Ambos retratos se eliminan, como en todas las demás ventanas."
L["The profession crafting window: recipe list, schematic, specializations, and crafting orders."] = "La ventana de fabricación de profesión: lista de recetas, esquema, especializaciones y pedidos de fabricación."
L["The professions overview book with squared icons and flat progress bars."] = "El libro de resumen de profesiones con iconos cuadrados y barras de progreso planas."
L["The ready check prompt with its Yes / No buttons, plus the initiator's response list."] = "El aviso de verificación de preparación con sus botones Sí / No, además de la lista de respuestas del iniciador."
L["The ready check prompt with its Yes / No buttons."] = "El aviso de verificación de preparación con sus botones Sí / No."
L["The recipe preview window shown from a linked recipe or an inspected crafter."] = "La ventana de vista previa de receta mostrada desde una receta enlazada o un artesano inspeccionado."
L["The refresh rate now bottoms out at 0.5s (lower saved values move up to it), trimming memory churn during combat."] = "La tasa de actualización ahora tiene un mínimo de 0.5s (los valores guardados más bajos suben hasta él), reduciendo el consumo de memoria durante el combate."
L["The scriptProfile CVar is enabled."] = "La CVar scriptProfile está activada."
L["The signature EllesmereUI layout exactly as designed. Vibrant class colors, clear cd tracking, and every module working in harmony."] = "La disposición insignia de EllesmereUI exactamente como fue diseñada. Colores de clase vibrantes, seguimiento claro de TR, y todos los módulos trabajando en armonía."
L["The single stack threshold is off while Multiple Thresholds is on."] = "El umbral de pila único está desactivado mientras Umbrales múltiples está activado."
L["The size of your mana pool"] = "El tamaño de tu reserva de maná"
L["The spell picker now ends with a Missing Spells? shortcut that opens Blizzard's Cooldown Manager so you can add spells that are not listed."] = "El selector de hechizos ahora termina con un acceso directo ¿Faltan hechizos? que abre el Gestor de tiempos de reutilización de Blizzard para que puedas añadir hechizos que no estén en la lista."
L["The standard buff grid"] = "La cuadrícula de beneficios estándar"
L["The standard debuff grid"] = "La cuadrícula de perjuicios estándar"
L["The stricter in-combat subset of the raid set."] = "El subconjunto más estricto en combate del conjunto de banda."
L["The taintLog CVar is enabled."] = "La CVar taintLog está activada."
L["The taintLog and scriptProfile CVars are enabled."] = "Las CVar taintLog y scriptProfile están activadas."
L["The target effect's border size no longer snaps back to normal while a cast bar is shown with Border Wraps Around Cast Bar enabled."] = "El tamaño del borde del efecto de objetivo ya no vuelve a la normalidad mientras se muestra una barra de lanzamiento con Borde envuelve la barra de lanzamiento activado."
L["The transmogrification window at the transmogrifier."] = "La ventana de transfiguración en el transfigurador."
L["The vendor window: item list, buyback, and bottom money bar."] = "La ventana de vendedor: lista de objetos, recompra y la barra de dinero inferior."
L["The widest angle a nest's entries may spread over."] = "El ángulo más amplio en el que pueden repartirse las entradas de un nido."
L["The widest angle a nest's entries may spread over. They stay on one ring for as long as they fit inside it; the rest go onto a second ring further out."] = "El ángulo más amplio en el que pueden repartirse las entradas de un nido. Permanecen en un anillo mientras encajen dentro de él; el resto pasa a un segundo anillo más externo."
L["The world map window chrome and the quest log side panel."] = "El marco de la ventana del mapa del mundo y el panel lateral del registro de misiones."
L["Themed Blizzard frames: Character Sheet, tooltips, menus, popups, Dragon Riding HUD."] = "Marcos de Blizzard con tema: Ficha de personaje, tooltips, menús, ventanas emergentes, HUD de vuelo de dragón."
L["Themed Blizzard frames: window skins, tooltips, menus, popups, Dragon Riding HUD."] = "Marcos de Blizzard con tema: skins de ventana, tooltips, menús, ventanas emergentes, HUD de vuelo de dragón."
L["These are the same settings found on each module's own pages, not separate ones."] = "Son los mismos ajustes que se encuentran en las propias páginas de cada módulo, no ajustes distintos."
L["These settings prioritize frame rate and visual clarity over environmental detail. Textures stay high quality so your character and the world still look perfect."] = "Estos ajustes priorizan la tasa de fotogramas y la claridad visual sobre el detalle ambiental. Las texturas se mantienen en alta calidad, de modo que tu personaje y el mundo siguen viéndose perfectos."
L["These specs hold override values that no group's editing mode can reach anymore (left behind by membership changes). They still apply. Remove one to return that spec to the shared default."] = "Estas especializaciones tienen valores de anulación a los que el modo de edición de ningún grupo puede acceder ya (dejados por cambios de pertenencia). Siguen aplicándose. Elimina una para devolver esa especialización al valor predeterminado compartido."
L["Thick"] = "Grueso"
L["Thickness"] = "Grosor"
L["Thickness applies to Solid Border and Pixel Glow"] = "El grosor se aplica a Borde sólido y Resplandor de píxeles"
L["Thickness in physical pixels for Solid Border and Pixel Glow."] = "Grosor en píxeles físicos para Borde sólido y Resplandor de píxeles."
L["Thickness in physical pixels. -1 follows the Debuff Manager's Border setting, 0 hides the dispel color border."] = "Grosor en píxeles físicos. -1 sigue el ajuste de Borde del Gestor de perjuicios, 0 oculta el borde de color de disipación."
L["Thickness of any Pixel Glow assigned to this bar's buttons. Assign glows by right-clicking an icon in the preview."] = "Grosor de cualquier Resplandor de píxeles asignado a los botones de esta barra. Asigna resplandores haciendo clic derecho en un icono de la vista previa."
L["Thickness of the Pixel Glow applied to this bar's buff icons."] = "Grosor del Resplandor de píxeles aplicado a los iconos de beneficio de esta barra."
L["Thin Line Bottom"] = "Línea fina inferior"
L["Thin Line Top"] = "Línea fina superior"
L["Third Timer"] = "Tercer temporizador"
L["This Action Bar is also used as the Moonkin Form bar.\nChanging spells on a Druid for this bar will also change them on your Moonkin Form bar."] = "Esta Barra de acción también se usa como la barra de Forma de lechúzico.\nCambiar hechizos en un druida para esta barra también los cambiará en tu barra de Forma de lechúzico." -- TODO: confirmar termo oficial
L["This Setting Has Overrides"] = "Este ajuste tiene anulaciones"
L["This bar has an Additional Bar Offset (X %1$s, Y %2$s) set in its options. Unlock mode shows the base position; the offset re-applies when you exit."] = "Esta barra tiene un Desplazamiento de barra adicional (X %1$s, Y %2$s) definido en sus opciones. El modo de desbloqueo muestra la posición base; el desplazamiento se vuelve a aplicar al salir."
L["This bar sizes its blocks itself, so the width is not this block's to choose."] = "Esta barra dimensiona sus bloques por sí misma, por lo que el ancho no depende de este bloque."
L["This bar will always be attached to your current target's nameplate"] = "Esta barra siempre estará anclada a la placa de nombre de tu objetivo actual"
L["This bar will always be attached to your focus target's nameplate"] = "Esta barra siempre estará anclada a la placa de nombre de tu objetivo de foco"
L["This bar will only show if you have an enemy targeted"] = "Esta barra solo se mostrará si tienes un enemigo como objetivo"
L["This block is already the 'Fill Remaining Space' block. Check another block to move the role."] = "Este bloque ya es el bloque de 'Rellenar espacio restante'. Marca otro bloque para mover ese rol."
L["This can't change which spells the user tracks in Blizzard's CDM.\nIt's recommended to also share your Blizzard CDM layout for any spec you choose here."] = "Esto no puede cambiar qué hechizos sigue el usuario en el CDM de Blizzard.\nSe recomienda compartir también tu disposición del CDM de Blizzard para cualquier especialización que elijas aquí."
L["This cannot be undone. Consider exporting this profile as a backup first."] = "Esto no se puede deshacer. Considera exportar primero este perfil como copia de seguridad."
L["This cannot be undone. Export your own profile as a backup first."] = "Esto no se puede deshacer. Exporta primero tu propio perfil como copia de seguridad."
L["This change requires a UI reload to take effect."] = "Este cambio requiere una recarga de la interfaz para surtir efecto."
L["This condition is coming in a future update."] = "Esta condición llegará en una futura actualización."
L["This conditional is not active right now. Meet one of its conditions first (for example, enter the dungeon) so you can arrange the layout in its real context."] = "Este condicional no está activo ahora mismo. Cumple primero una de sus condiciones (por ejemplo, entrar en la mazmorra) para poder organizar la disposición en su contexto real."
L["This control recently changed direction: it now copies FROM the frame you choose. Confirming will copy all shared settings FROM %1$s TO %2$s."] = "Este control cambió de dirección recientemente: ahora copia DESDE el marco que elijas. Confirmar copiará todos los ajustes compartidos DESDE %1$s HACIA %2$s."
L["This element cannot use group-based visibility."] = "Este elemento no puede usar visibilidad basada en grupo."
L["This element doesn't support both Height and Width matching"] = "Este elemento no admite el ajuste tanto de Altura como de Ancho a la vez"
L["This element shows as soon as ONE Show condition matches. Hide keeps its meaning in both match modes: a checked Hide always hides, on every row."] = "Este elemento se muestra en cuanto UNA condición de Mostrar coincide. Ocultar mantiene su significado en ambos modos de coincidencia: un Ocultar marcado siempre oculta, en todas las filas."
L["This element shows as soon as ONE condition matches, and a Hide lane then means show while that condition is false."] = "Este elemento se muestra en cuanto UNA condición coincide, y un carril Ocultar entonces significa mostrar mientras esa condición sea falsa."
L["This element will only show while you are inside a house or plot"] = "Este elemento solo se mostrará mientras estés dentro de una casa o parcela"
L["This element will only show while you are mounted"] = "Este elemento solo se mostrará mientras estés montado"

-- == Batch 56 (missing_esES.txt): This export includes cross profile settings...Toggle visibility of item level text on the character sheet. ====
L["This export includes cross profile settings that will overwrite the importing user's settings including Quality of Life, Hovercast and more that should typically not be shared with standard profiles. THIS IS NOT RECOMMENDED for public sharing of profiles."] = "Esta exportación incluye ajustes multiperfil que sobrescribirán los ajustes del usuario que la importe, incluyendo Calidad de vida, Hovercast y más, que normalmente no deberían compartirse con perfiles estándar. NO SE RECOMIENDA compartir esto públicamente."
L["This feature optimizes your in-game graphics settings to give you the best combination of high FPS and visual clarity.\n\nYou can revert all changes at any time by clicking \"Restore My Settings\" which will appear after optimizing.\n\n\nWhat we change:\n\n"] = "Esta función optimiza tus ajustes de gráficos del juego para darte la mejor combinación de FPS altos y claridad visual.\n\nPuedes revertir todos los cambios en cualquier momento haciendo clic en \"Restaurar mis ajustes\", que aparecerá después de optimizar.\n\n\nQué cambiamos:\n\n"
L["This feature optimizes your in-game graphics settings to give you the best combination of high FPS and visual clarity.\n\nYou can revert all changes at any time by clicking \"Restore My Settings\" which will appear after optimizing.\n\n\nWhat we change:\n\nShadow Quality - Fair (balanced quality/FPS)\nLiquid Detail - Disabled\nParticle Density - Set to Ultra (keeps important spell effects)\nSSAO (Ambient Occlusion) - Disabled\nDepth Effects - Disabled\nCompute Effects - Disabled\nOutline Mode - Disabled\nTexture Resolution - Set to High\nSpell Density - Set to Essential\nProjected Textures - Enabled (needed for ground effects)\nView Distance - Reduced to 1\nEnvironment Detail - Reduced to 1\nGround Clutter - Reduced to 1\nRaid/Dungeon Settings - Uses same settings everywhere\nResample Sharpening - Enabled (crisper image)\nContrast - Boosted by +10 (if currently 55 or below)\nEnable Reverb - Disabled (spell and interrupt audio cues stay crisp)\n\nThese settings prioritize frame rate and visual clarity over environmental detail. Textures stay high quality so your character and the world still look perfect."] = "Esta función optimiza tus ajustes de gráficos del juego para darte la mejor combinación de FPS altos y claridad visual.\n\nPuedes revertir todos los cambios en cualquier momento haciendo clic en \"Restaurar mis ajustes\", que aparecerá después de optimizar.\n\n\nQué cambiamos:\n\nCalidad de sombras - Aceptable (equilibrio calidad/FPS)\nDetalle de líquidos - Desactivado\nDensidad de partículas - Establecida en Ultra (mantiene los efectos de hechizo importantes)\nSSAO (oclusión ambiental) - Desactivado\nEfectos de profundidad - Desactivados\nEfectos de cómputo - Desactivados\nModo de contorno - Desactivado\nResolución de textura - Establecida en Alta\nDensidad de hechizos - Establecida en Esencial\nTexturas proyectadas - Activadas (necesarias para efectos de suelo)\nDistancia de visión - Reducida a 1\nDetalle del entorno - Reducido a 1\nVegetación del suelo - Reducida a 1\nAjustes de banda/mazmorra - Usa los mismos ajustes en todas partes\nNitidez por remuestreo - Activada (imagen más nítida)\nContraste - Aumentado en +10 (si actualmente es 55 o menos)\nActivar reverberación - Desactivado (las señales de audio de hechizos e interrupciones se mantienen nítidas)\n\nEstos ajustes priorizan la tasa de fotogramas y la claridad visual sobre el detalle ambiental. Las texturas se mantienen en alta calidad, de modo que tu personaje y el mundo siguen viéndose perfectos."
L["This feature requires Snap Elements to be enabled"] = "Esta función requiere que Ajustar elementos esté activado"
L["This feature runs continuous range checks against every visible enemy nameplate. It is one of the more expensive features in EllesmereUI and can measurably increase CPU usage in crowded areas."] = "Esta función ejecuta comprobaciones de alcance continuas contra cada placa de nombre enemiga visible. Es una de las funciones más costosas de EllesmereUI y puede aumentar de forma apreciable el uso de CPU en zonas concurridas."
L["This frame's source changes require a UI reload to take effect."] = "Los cambios de origen de este marco requieren una recarga de la interfaz para surtir efecto."
L["This group's custom Buff Manager can only be activated or edited while playing one of its specs."] = "El Gestor de beneficios personalizado de este grupo solo se puede activar o editar mientras juegas con una de sus especializaciones."
L["This group's custom Debuff Manager can only be activated or edited while playing one of its specs."] = "El Gestor de perjuicios personalizado de este grupo solo se puede activar o editar mientras juegas con una de sus especializaciones."
L["This is a voice preview"] = "Esta es una vista previa de voz"
L["This is the Spell Queue Window, it helps with making sure you can't queue up too many spells at once which makes the game feel laggy. Recommended settings are generally a minimum of 200 + your local ping. If you are unsure of exactly what this setting does, leave it at 400."] = "Esta es la Ventana de cola de hechizos; ayuda a asegurar que no puedas encolar demasiados hechizos a la vez, lo que hace que el juego se sienta lento. Los ajustes recomendados suelen ser un mínimo de 200 + tu ping local. Si no estás seguro de qué hace exactamente este ajuste, déjalo en 400."
L["This is the Spell Queue Window, it helps with making sure you can't queue up too many spells at once which makes the game feel laggy. Recommended settings are generally ~150 for melee and ~300 for casters. Higher if you have high local ping."] = "Esta es la Ventana de cola de hechizos; ayuda a asegurar que no puedas encolar demasiados hechizos a la vez, lo que hace que el juego se sienta lento. Los ajustes recomendados suelen ser ~150 para cuerpo a cuerpo y ~300 para lanzadores. Más alto si tienes un ping local alto."
L["This is the full overlay that swipes from right to left on the icon during its cast duration"] = "Esta es la superposición completa que barre de derecha a izquierda sobre el icono durante su duración de lanzamiento"
L["This is the spec you're syncing from -- it's always included."] = "Esta es la especialización desde la que sincronizas -- siempre está incluida."
L["This is where you can control the settings of Unlock Mode.\n\nElements can be repositioned by dragging or arrow keys (+shift)\nAnchor, Height Match, or Width match any element.\nSnapping is based on closest element, but you can snap only to\n a specific element via right click or the settings icon."] = "Aquí es donde puedes controlar los ajustes del Modo de desbloqueo.\n\nLos elementos se pueden reposicionar arrastrándolos o con las teclas de flecha (+mayús)\nAncla, iguala la altura o el ancho a cualquier elemento.\nEl ajuste se basa en el elemento más cercano, pero puedes ajustar solo a\n un elemento específico mediante clic derecho o el icono de ajustes."
L["This makes it so the width of the cast bar includes the icon, rather than placing it to the left of the cast bars width."] = "Esto hace que el ancho de la barra de lanzamiento incluya el icono, en lugar de colocarlo a la izquierda del ancho de la barra de lanzamiento."
L["This module can't be overridden. Exit the override editing session to open it."] = "Este módulo no se puede anular. Sal de la sesión de edición de anulación para abrirlo."
L["This module is excluded from Spec Overrides."] = "Este módulo está excluido de las Anulaciones de especialización."
L["This option Show Duration (Inside Cog) Enabled"] = "Esta opción tiene Mostrar duración (dentro del engranaje) activado"
L["This option allows you to set custom frame sizing and positioning to different raid sizes. Note: This does NOT resize/reposition frames while in combat, if players join/leave mid combat it will resize after combat completes."] = "Esta opción te permite establecer un tamaño y posición de marco personalizados para distintos tamaños de banda. Nota: esto NO redimensiona/reposiciona los marcos durante el combate; si los jugadores se unen/salen a mitad de combate, se redimensionará al terminar el combate."
L["This option applies to bar-type resources only (pips use stack counts)."] = "Esta opción se aplica solo a los recursos de tipo barra (los indicadores usan números de pila)."
L["This option applies to pip-type resources only."] = "Esta opción se aplica solo a los recursos de tipo indicador."
L["This option can't be used while Expand Power Bar if No Resource is enabled."] = "Esta opción no se puede usar mientras Expandir barra de poder si no hay recurso está activado."
L["This option can't be used while Shift Elements if No Resource is enabled."] = "Esta opción no se puede usar mientras Desplazar elementos si no hay recurso está activado."
L["This option can't be used while you have the Power Bar Height Matched in the Unlock Mode."] = "Esta opción no se puede usar mientras tengas la Altura de la barra de poder igualada en el Modo de desbloqueo."
L["This option does not apply while Anchor to Cursor is enabled"] = "Esta opción no se aplica mientras Anclar al cursor esté activado"
L["This option does not work with Blizzard Bars. Please use Blizzard Edit Mode."] = "Esta opción no funciona con las Barras de Blizzard. Usa el Modo de edición de Blizzard."
L["This option is currently under maintenance"] = "Esta opción está actualmente en mantenimiento"
L["This option is disabled while a Center Text is selected."] = "Esta opción está desactivada mientras haya un Texto central seleccionado."
L["This option is not available for custom shaped icons"] = "Esta opción no está disponible para iconos de forma personalizada"
L["This option is not supported for this bar type"] = "Esta opción no es compatible con este tipo de barra"
L["This option is now controlled by the Raid Frames addon"] = "Esta opción ahora está controlada por el addon Marcos de banda"
L["This option is only available for abilities with multiple charges"] = "Esta opción solo está disponible para habilidades con varias cargas"
L["This option is only available for formats that display a percentage."] = "Esta opción solo está disponible para formatos que muestran un porcentaje."
L["This option is only available for the Custom Color Theme"] = "Esta opción solo está disponible para el Tema de color personalizado"
L["This option is only available when Portrait Mode is Detached."] = "Esta opción solo está disponible cuando el Modo de retrato es Separado."
L["This option is only used by the Basic border."] = "Esta opción solo la usa el borde Básico."
L["This option only affects Raid Buffs and Paladin Beacons"] = "Esta opción solo afecta a los Beneficios de banda y los Faros de paladín"
L["This option requires %s to be enabled"] = "Esta opción requiere que %s esté activado"
L["This option requires <text> to be enabled"] = "Esta opción requiere que <text> esté activado"
L["This option requires Add Friendly Boss Group to be set to Healers or Always."] = "Esta opción requiere que Añadir grupo de jefe amistoso esté establecido en Sanadores o Siempre."
L["This option requires Blizzard Style Action Bars to be disabled"] = "Esta opción requiere que Barras de acción de estilo Blizzard esté desactivado"
L["This option requires Blizzard's Assisted Highlight to be enabled"] = "Esta opción requiere que el Resaltado asistido de Blizzard esté activado"
L["This option requires Class Colors to be disabled"] = "Esta opción requiere que Colores de clase esté desactivado"
L["This option requires Class Resource to be set to Modern."] = "Esta opción requiere que Recurso de clase esté establecido en Moderno."
L["This option requires Combine Spell Name and Target to be disabled."] = "Esta opción requiere que Combinar nombre de hechizo y objetivo esté desactivado."
L["This option requires Countdown Format to count GCDs inside Arcane Soul"] = "Esta opción requiere que el Formato de cuenta atrás cuente TGC dentro de Alma arcana"
L["This option requires Dark Mode Class Resource to be disabled. Dark Mode colors can be adjusted in Global Settings -> Fonts & Colors."] = "Esta opción requiere que Recurso de clase en Modo oscuro esté desactivado. Los colores del Modo oscuro se pueden ajustar en Ajustes globales -> Fuentes y colores."
L["This option requires Display Style to be set to Icon"] = "Esta opción requiere que Estilo de visualización esté establecido en Icono"
L["This option requires Display Style to be set to Text"] = "Esta opción requiere que Estilo de visualización esté establecido en Texto"
L["This option requires Fill Color to be set to Custom"] = "Esta opción requiere que Color de relleno esté establecido en Personalizado"
L["This option requires Icon Shape to be set to None or Cropped"] = "Esta opción requiere que Forma del icono esté establecida en Ninguna o Recortada"
L["This option requires Pixel Glow to be the selected glow type"] = "Esta opción requiere que Resplandor de píxeles sea el tipo de resplandor seleccionado"
L["This option requires Portrait Mode to be set to Detached."] = "Esta opción requiere que el Modo de retrato esté establecido en Separado."
L["This option requires Set UI Scale to 0.5333 to be disabled"] = "Esta opción requiere que Establecer escala de interfaz en 0.5333 esté desactivado"
L["This option requires Show Tanks in Extra Group or a bound hotkey."] = "Esta opción requiere Mostrar tanques en grupo extra o una tecla rápida asignada."
L["This option requires Show Tooltips to be set to hide tooltips"] = "Esta opción requiere que Mostrar tooltips esté establecido para ocultar tooltips"
L["This option requires Split Compare to include a key level"] = "Esta opción requiere que Comparación de divisiones incluya un nivel de llave"
L["This option requires Subtitle Text to include the Guild Name"] = "Esta opción requiere que el Texto de subtítulo incluya el Nombre de hermandad"
L["This option requires Threshold Settings to be disabled"] = "Esta opción requiere que los Ajustes de umbral estén desactivados"
L["This option requires Tooltips to be set to Shown on Modifier"] = "Esta opción requiere que Tooltips esté establecido en Mostrado con modificador"
L["This option requires a Border Size above 0."] = "Esta opción requiere un Tamaño de borde mayor que 0."
L["This option requires a Class Icon other than None."] = "Esta opción requiere un Icono de clase distinto de Ninguno."
L["This option requires a Duration Text position other than None"] = "Esta opción requiere una posición de Texto de duración distinta de Ninguna"
L["This option requires a Glow Type other than None"] = "Esta opción requiere un Tipo de resplandor distinto de Ninguno"
L["This option requires a Health Text format other than None"] = "Esta opción requiere un formato de Texto de vida distinto de Ninguno"
L["This option requires a Name Text position other than None"] = "Esta opción requiere una posición de Texto de nombre distinta de Ninguna"
L["This option requires a Power Text format other than None"] = "Esta opción requiere un formato de Texto de poder distinto de Ninguno"
L["This option requires a Split Compare mode"] = "Esta opción requiere un modo de Comparación de divisiones"
L["This option requires a Stacks Text position other than None"] = "Esta opción requiere una posición de Texto de pilas distinta de Ninguna"
L["This option requires a cooldown-tracking bar"] = "Esta opción requiere una barra de seguimiento de tiempo de reutilización"
L["This option requires a custom glow to be selected"] = "Esta opción requiere que se seleccione un resplandor personalizado"
L["This option requires a custom thickness to be set."] = "Esta opción requiere que se establezca un grosor personalizado."
L["This option requires a detached position to be active."] = "Esta opción requiere que una posición separada esté activa."
L["This option requires a dropdown selection other than Above Health Bar"] = "Esta opción requiere una selección de menú desplegable distinta de Sobre la barra de vida"
L["This option requires a gradient to be set"] = "Esta opción requiere que se establezca un degradado"
L["This option requires a non-custom button shape"] = "Esta opción requiere una forma de botón no personalizada"
L["This option requires a non-custom shape to be selected"] = "Esta opción requiere que se seleccione una forma no personalizada"
L["This option requires a non-custom shaped action bar"] = "Esta opción requiere una barra de acción de forma no personalizada"
L["This option requires a perpendicular Group Growth"] = "Esta opción requiere un Crecimiento de grupo perpendicular"
L["This option requires a style that draws the glow ring"] = "Esta opción requiere un estilo que dibuje el anillo de resplandor"
L["This option requires a text position other than none."] = "Esta opción requiere una posición de texto distinta de ninguna."
L["This option requires a text selection other than none."] = "Esta opción requiere una selección de texto distinta de ninguna."
L["This option requires a text to be assigned"] = "Esta opción requiere que se asigne un texto"
L["This option requires an aura or indicator to be assigned"] = "Esta opción requiere que se asigne un aura o indicador"
L["This option requires exactly 2 rows"] = "Esta opción requiere exactamente 2 filas"
L["This option requires the Border Style to be set to Solid"] = "Esta opción requiere que el Estilo de borde esté establecido en Sólido"
L["This option requires the Button Overlay style"] = "Esta opción requiere el estilo de Superposición de botón"
L["This option requires the module to be enabled"] = "Esta opción requiere que el módulo esté activado"
L["This option requires the position setting to be detached"] = "Esta opción requiere que el ajuste de posición esté separado"
L["This override has no indicators for this spec, so nothing shows here until you add some."] = "Esta anulación no tiene indicadores para esta especialización, así que aquí no se muestra nada hasta que añadas alguno."
L["This overwrites the chosen frame's current settings. Frame position, visibility, and enable state are not changed."] = "Esto sobrescribe los ajustes actuales del marco elegido. La posición, visibilidad y estado de activación del marco no cambian."
L["This overwrites this action menu's current settings. Its actions, name, and keybind are not changed."] = "Esto sobrescribe los ajustes actuales de este menú de acciones. Sus acciones, nombre y atajo de teclado no cambian."
L["This overwrites this frame's current settings. Frame position, visibility, and enable state are not changed."] = "Esto sobrescribe los ajustes actuales de este marco. La posición, visibilidad y estado de activación del marco no cambian."
L["This page is excluded from overrides."] = "Esta página está excluida de las anulaciones."
L["This permanently overwrites this profile's settings with the override '%s': its captured settings and its custom Unlock Mode and Buff Manager layouts (where present) become the profile's own baseline for every spec. ALL spec override groups on this profile are then deleted and the UI reloads. Conditional overrides are not affected."] = "Esto sobrescribe permanentemente los ajustes de este perfil con la anulación '%s': sus ajustes capturados y sus disposiciones personalizadas de Modo de desbloqueo y Gestor de beneficios (donde existan) se convierten en la base propia del perfil para todas las especializaciones. Después se eliminan TODOS los grupos de anulación de especialización de este perfil y se recarga la interfaz. Las anulaciones condicionales no se ven afectadas."
L["This preset"] = "Este preajuste"
L["This profile already holds 16 action menus"] = "Este perfil ya tiene 16 menús de acciones"
L["This profile string does not carry any Window & Tooltip Skins settings."] = "Esta cadena de perfil no contiene ningún ajuste de Skins de ventana y tooltip."
L["This profile string does not carry any global settings."] = "Esta cadena de perfil no contiene ningún ajuste global."
L["This profile string does not carry any override data."] = "Esta cadena de perfil no contiene ningún dato de anulación."
L["This profile was made at %1$d%% UI scale; yours is %2$d%%. Change your UI scale to match the imported profile? This will show all profiles at this scale as UI Scale is not a per-profile setting, but can be changed at any time back to your original value."] = "Este perfil se creó a una escala de interfaz del %1$d%%; la tuya es del %2$d%%. ¿Cambiar tu escala de interfaz para que coincida con el perfil importado? Esto mostrará todos los perfiles a esta escala, ya que la Escala de interfaz no es un ajuste por perfil, pero se puede cambiar en cualquier momento de vuelta a tu valor original."
L["This replaces %d existing value(s) for this setting across your specs."] = "Esto sustituye %d valor(es) existente(s) para este ajuste en todas tus especializaciones."
L["This replaces %d existing value(s) for this setting across your specs. Do you want to continue?"] = "Esto sustituye %d valor(es) existente(s) para este ajuste en todas tus especializaciones. ¿Quieres continuar?"
L["This replaces %d existing value(s) for this setting on this bar."] = "Esto sustituye %d valor(es) existente(s) para este ajuste en esta barra."
L["This replaces %d existing value(s) for this setting on this bar. Do you want to continue?"] = "Esto sustituye %d valor(es) existente(s) para este ajuste en esta barra. ¿Quieres continuar?"
L["This replaces 3 existing value(s) for this setting across your specs. Do you want to continue?"] = "Esto sustituye 3 valor(es) existente(s) para este ajuste en todas tus especializaciones. ¿Quieres continuar?"
L["This resets every EUI addon, not just the current one."] = "Esto restablece todos los addons de EUI, no solo el actual."
L["This setting already has an override for %s"] = "Este ajuste ya tiene una anulación para %s"
L["This setting can't be overridden."] = "Este ajuste no se puede anular."
L["This setting requires a UI reload to take effect."] = "Este ajuste requiere una recarga de la interfaz para surtir efecto."
L["This setting's active Apply to Bar (All Specs) value will be replaced."] = "El valor activo de Aplicar a la barra (todas las especializaciones) de este ajuste será sustituido."
L["This setting's active Apply to Bar value will be replaced."] = "El valor activo de Aplicar a la barra de este ajuste será sustituido."
L["This spec doesn't have this spell."] = "Esta especialización no tiene este hechizo."
L["This spec's custom unlock mode is owned by '%s'. Customize it there, or remove the spec from that group."] = "El modo de desbloqueo personalizado de esta especialización pertenece a '%s'. Personalízalo allí, o elimina la especialización de ese grupo."
L["This spell"] = "Este hechizo"
L["This spell is already being used on %s"] = "Este hechizo ya se está usando en %s"
L["This string is a FULL ACCOUNT export. It replaces your account-wide settings with the sender's, including Quality of Life, HoverCast bindings, Cooldown Manager spell setups, unlock anchors, UI scale, and profile keybinds -- not just a profile. Your other profiles are kept, but a profile with the same name is replaced."] = "Esta cadena es una exportación de CUENTA COMPLETA. Sustituye tus ajustes de toda la cuenta por los del remitente, incluyendo Calidad de vida, atajos de HoverCast, configuraciones de hechizo del Gestor de tiempos de reutilización, anclas de desbloqueo, escala de interfaz y atajos de teclado de perfil -- no solo un perfil. Tus otros perfiles se conservan, pero un perfil con el mismo nombre se sustituye."
L["This unit uses the Blizzard default frame -- there are no EllesmereUI settings to configure here."] = "Esta unidad usa el marco predeterminado de Blizzard -- no hay ajustes de EllesmereUI que configurar aquí."
L["This unit's frame is hidden -- there are no EllesmereUI settings to configure here."] = "El marco de esta unidad está oculto -- no hay ajustes de EllesmereUI que configurar aquí."
L["This will change the color of your bar if you have more than your chosen number of stacks"] = "Esto cambiará el color de tu barra si tienes más pilas que el número elegido"
L["This will create a fully unique Buff Manager for this conditional group. Changes made to your default Buff Manager will no longer affect it."] = "Esto creará un Gestor de beneficios totalmente único para este grupo condicional. Los cambios hechos en tu Gestor de beneficios predeterminado ya no lo afectarán."
L["This will create a fully unique Buff Manager for this conditional group. Your current Buff Manager settings are copied as its starting point, and changes made to your default Buff Manager will no longer affect it."] = "Esto creará un Gestor de beneficios totalmente único para este grupo condicional. Tus ajustes actuales del Gestor de beneficios se copian como punto de partida, y los cambios hechos en tu Gestor de beneficios predeterminado ya no lo afectarán."
L["This will create a fully unique Buff Manager for this override group. Changes made to your default Buff Manager will no longer affect these specs."] = "Esto creará un Gestor de beneficios totalmente único para este grupo de anulación. Los cambios hechos en tu Gestor de beneficios predeterminado ya no afectarán a estas especializaciones."
L["This will create a fully unique Buff Manager for this override group. Your current Buff Manager settings are copied as its starting point, and changes made to your default Buff Manager will no longer affect these specs."] = "Esto creará un Gestor de beneficios totalmente único para este grupo de anulación. Tus ajustes actuales del Gestor de beneficios se copian como punto de partida, y los cambios hechos en tu Gestor de beneficios predeterminado ya no afectarán a estas especializaciones."
L["This will create a fully unique Debuff Manager for this conditional group. Your current Debuff Manager settings are copied as its starting point, and changes made to your default Debuff Manager will no longer affect it."] = "Esto creará un Gestor de perjuicios totalmente único para este grupo condicional. Tus ajustes actuales del Gestor de perjuicios se copian como punto de partida, y los cambios hechos en tu Gestor de perjuicios predeterminado ya no lo afectarán."
L["This will create a fully unique Debuff Manager for this override group. Your current Debuff Manager settings are copied as its starting point, and changes made to your default Debuff Manager will no longer affect these specs."] = "Esto creará un Gestor de perjuicios totalmente único para este grupo de anulación. Tus ajustes actuales del Gestor de perjuicios se copian como punto de partida, y los cambios hechos en tu Gestor de perjuicios predeterminado ya no afectarán a estas especializaciones."
L["This will create a fully unique unlock mode for this conditional group. Changes made to your default unlock mode will no longer affect it."] = "Esto creará un modo de desbloqueo totalmente único para este grupo condicional. Los cambios hechos en tu modo de desbloqueo predeterminado ya no lo afectarán."
L["This will create a fully unique unlock mode for this override group. Changes made to your default unlock mode will no longer affect these specs."] = "Esto creará un modo de desbloqueo totalmente único para este grupo de anulación. Los cambios hechos en tu modo de desbloqueo predeterminado ya no afectarán a estas especializaciones."
L["This will disable EllesmereUI Tracking Bars and show Blizzard's default Tracked Bars display instead."] = "Esto desactivará las Barras de seguimiento de EllesmereUI y mostrará en su lugar la visualización predeterminada de Barras seguidas de Blizzard."
L["This will discard your custom party settings for this section and use raid settings instead."] = "Esto descartará tus ajustes de grupo personalizados para esta sección y usará en su lugar los ajustes de banda."
L["This will display ALL of your debuffs on enemy nameplates, rather than only the important ones."] = "Esto mostrará TODOS tus perjuicios en las placas de nombre enemigas, en lugar de solo los importantes."
L["This will display the word \"FOCUS\" below caster/miniboss mobs in M+ if you have not set your focus. Disabled for specs with no kick."] = "Esto mostrará la palabra \"FOCO\" debajo de los mobs lanzadores/minijefes en M+ si no has definido tu foco. Desactivado para especializaciones sin interrupción."
L["This will keep appearing each login until the layout is correct."] = "Esto seguirá apareciendo en cada inicio de sesión hasta que la disposición sea correcta."
L["This will not override sorting by role"] = "Esto no anulará la ordenación por rol"
L["This will not reset addon-specific Quick Setup."] = "Esto no restablecerá la Configuración rápida específica del addon."
L["This will overwrite %1$s settings on the selected profiles with your current settings. Continue?"] = "Esto sobrescribirá los ajustes de %1$s en los perfiles seleccionados con tus ajustes actuales. ¿Continuar?"
L["This will physically scatter items to random positions in your bags. The changes persist even if you disable EllesmereUI Bags."] = "Esto dispersará físicamente los objetos a posiciones aleatorias en tus bolsas. Los cambios persisten incluso si desactivas EllesmereUI Bags."
L["This will pin your bar to the window when it is not within the visible area"] = "Esto anclará tu barra a la ventana cuando no esté dentro del área visible"
L["This will replace YOUR Blizz UI Enhanced settings (the Window Skins and Tooltips, Menus & Popups tabs) with the sharer's, across ALL of your profiles. Your current settings on those two tabs cannot be recovered afterward."] = "Esto sustituirá TUS ajustes de Blizz UI Enhanced (las pestañas de Skins de ventana y Tooltips, menús y ventanas emergentes) por los de quien los comparte, en TODOS tus perfiles. Tus ajustes actuales en esas dos pestañas no se podrán recuperar después."
L["This will reset all default bar spell assignments for the current spec to match Blizzard's CDM layout. Custom bars are not affected. Continue?"] = "Esto restablecerá todas las asignaciones de hechizo predeterminadas de barra para la especialización actual para que coincidan con la disposición del CDM de Blizzard. Las barras personalizadas no se ven afectadas. ¿Continuar?"
L["This will reset all default bar spell assignments for the current spec to match Blizzard's CDM layout. Spells you added yourself (presets, custom IDs and racials) are kept. Continue?"] = "Esto restablecerá todas las asignaciones de hechizo predeterminadas de barra para la especialización actual para que coincidan con la disposición del CDM de Blizzard. Los hechizos que añadiste tú mismo (preajustes, ID personalizados y raciales) se conservan. ¿Continuar?"
L["This will reset all saved panel positions and reload your UI."] = "Esto restablecerá todas las posiciones de panel guardadas y recargará tu interfaz."
L["This will reset all saved panel positions and zoom levels and reload your UI."] = "Esto restablecerá todas las posiciones de panel y niveles de zoom guardados y recargará tu interfaz."
