L["Threshold and band colors work on the Whirlwind and Sweeping Strikes charge bar again, drawn as color ranges along the fill"] = "Los colores de umbral y banda vuelven a funcionar en la barra de cargas de Torbellino y Golpes amplios, dibujados como rangos de color a lo largo del relleno"
