L["Tint an entry that would do nothing right now: red when the target is out of range, blue when you are short of the resource, and gray when the game refuses it for any other reason. Spells and items only -- the game reports every toy as unusable, and a macro's usability depends on what its body resolves to."] = "Tiñe una entrada que ahora mismo no haría nada: rojo cuando el objetivo está fuera de alcance, azul cuando te falta el recurso, y gris cuando el juego lo rechaza por cualquier otro motivo. Solo hechizos y objetos -- el juego indica que todo juguete no se puede usar, y la usabilidad de una macro depende de a qué se resuelva su cuerpo."
L["Tint the bar with the Important colour when the enemy casts a spell the game flags as important."] = "Tiñe la barra con el color de Importante cuando el enemigo lanza un hechizo que el juego marca como importante."
L["Tint the cast bar with the Important colour when the enemy casts a spell the game flags as important. Overrides the Interruptible Cast colour; your interrupt being on cooldown still takes priority."] = "Tiñe la barra de lanzamiento con el color de Importante cuando el enemigo lanza un hechizo que el juego marca como importante. Anula el color de Lanzamiento interrumpible; que tu interrupción esté en tiempo de reutilización sigue teniendo prioridad."
L["Tint the cast bar with the Important colour when the unit casts a spell the game flags as important. Your interrupt being on cooldown still takes priority."] = "Tiñe la barra de lanzamiento con el color de Importante cuando la unidad lanza un hechizo que el juego marca como importante. Que tu interrupción esté en tiempo de reutilización sigue teniendo prioridad."
L["Tint the combat icon by the member's class color. Not available for the Arcade/Dungeoneer/Classic/Cross/Circle/Square styles."] = "Tiñe el icono de combate según el color de clase del miembro. No disponible para los estilos Arcade/Mazmorrero/Clásico/Cruz/Círculo/Cuadrado."
L["Tints the pattern with the bar's current color instead of the custom overlay color."] = "Tiñe el patrón con el color actual de la barra en lugar del color de superposición personalizado."
