L["Use a world marker entry again to pick that marker back up. Off places the marker again, at the new position.\nThis does not change the entry that clears all world markers, or the cycling entry."] = "Usa de nuevo una entrada de marcador del mundo para recoger ese marcador otra vez. Desactivado coloca el marcador de nuevo, en la nueva posición.\nEsto no cambia la entrada que borra todos los marcadores del mundo, ni la entrada de ciclo."
L["Use arrow keys to move selected element 1px any direction"] = "Usa las teclas de flecha para mover el elemento seleccionado 1px en cualquier dirección"
L["Use the dropdown above to add a new bar"] = "Usa el menú desplegable de arriba para añadir una nueva barra"
L["Use unique backgrounds for each bar"] = "Usa fondos únicos para cada barra"
L["Used by the movement alert's Bar display mode."] = "Lo usa el modo de visualización de Barra de la alerta de movimiento."
L["User-created info bars: clock, gold, XP, micro menu and more."] = "Barras de información creadas por el usuario: reloj, oro, EXP, micromenú y más."
L["Uses Blizzard's coin textures instead of the letter suffixes."] = "Usa las texturas de monedas de Blizzard en lugar de los sufijos de letra."
L["Uses Blizzard's own party switch, independent of the other channels. Instance chat, the one an LFG or LFR group talks in, is covered here too."] = "Usa el propio interruptor de grupo de Blizzard, independiente de los demás canales. El chat de instancia, en el que habla un grupo de LFG o LFR, también queda cubierto aquí."
L["Uses Blizzard's own raid switch, which it ships off. Ticking this turns that switch on, and it is put back the way you had it when you untick it or switch the feature off."] = "Usa el propio interruptor de banda de Blizzard, que viene desactivado de fábrica. Marcar esto activa ese interruptor, y se restaura como lo tenías al desmarcarlo o al desactivar la función."
L["Uses a random hearthstone toy variant each cast."] = "Usa una variante de juguete de piedra de hogar aleatoria en cada lanzamiento."
L["Uses the Hover Effect color and opacity. Set to None for the flat hover highlight."] = "Usa el color y la opacidad del Efecto al pasar el ratón. Establece en Ninguno para el resaltado plano al pasar el ratón."
L["Uses the entry you are pointing at while a menu is kept open with Toggle Menu Open. One key shared by every menu, claimed only while a menu is up -- a mouse button keeps its normal use the rest of the time."] = "Usa la entrada que estás señalando mientras un menú se mantiene abierto con Alternar menú abierto. Una tecla compartida por todos los menús, reclamada solo mientras un menú está abierto -- un botón del ratón mantiene su uso normal el resto del tiempo."
L["Uses the entry you are pointing at while a menu is kept open with Toggle Menu Open. One key shared by every menu, claimed only while a menu is up -- a mouse button keeps its normal use the rest of the time.\n\nLeft-click to set a keybind, then press any key or\nclick any mouse button to use it.\nEscape cancels. Right-click here to unbind."] = "Usa la entrada que estás señalando mientras un menú se mantiene abierto con Alternar menú abierto. Una tecla compartida por todos los menús, reclamada solo mientras un menú está abierto -- un botón del ratón mantiene su uso normal el resto del tiempo.\n\nClic izquierdo para definir un atajo de teclado, luego pulsa cualquier tecla o\nhaz clic en cualquier botón del ratón para usarlo.\nEscape cancela. Clic derecho aquí para desasignarlo."
L["Utility"] = "Utilidad"
