L["Weekly and event choice windows such as Abundance harvests and \"how will you aid...\" pickers: option plates, headers, reward icons and buttons. Option artwork stays."] = "Ventanas de elección semanal y de evento, como las cosechas de Abundancia y los selectores de \"cómo ayudarás...\": placas de opción, encabezados, iconos de recompensa y botones. El arte de las opciones se mantiene."
