L["Welcome to EllesmereUI"] = "Bienvenido a EllesmereUI"
L["What sits between the crest amounts."] = "Lo que se sitúa entre las cantidades de cresta."
L["What sits in front of the number. Icon shows the character icon; the color swatches on the left tint it."] = "Lo que se sitúa delante del número. Icono muestra el icono del personaje; las muestras de color de la izquierda lo tiñen."
L["What's new in EllesmereUI."] = "Qué hay de nuevo en EllesmereUI."
