L["When Dragonriding"] = "Durante el vuelo de dragón"
L["When Healing"] = "Al curar"
L["When Not Dragonriding"] = "Fuera del vuelo de dragón"
L["When Present"] = "Cuando esté presente"
L["When disabled, EUI relinquishes full control of friendly player nameplates to Blizzard. Use Blizzard's own Nameplate settings (Esc > Options > Nameplates) to control them."] = "Cuando está desactivado, EUI cede el control total de las placas de nombre de jugadores amistosos a Blizzard. Usa los propios ajustes de Placas de nombre de Blizzard (Esc > Opciones > Placas de nombre) para controlarlas."
L["When enabled, BM and MM specs show Focus as the standard power bar instead of a class resource bar."] = "Cuando está activado, las especializaciones de Dominio de bestias y Puntería muestran Foco como la barra de poder estándar en lugar de una barra de recurso de clase."
L["When enabled, EUI relinquishes full control of friendly player nameplates to Blizzard."] = "Cuando está activado, EUI cede el control total de las placas de nombre de jugadores amistosos a Blizzard."
L["When enabled, Shift+Click any minimap button (mail, calendar, tracking, addon buttons) to drag it to a custom position."] = "Cuando está activado, Mayús+clic en cualquier botón del minimapa (correo, calendario, seguimiento, botones de addon) para arrastrarlo a una posición personalizada."
L["When enabled, Shift+Click any minimap button (mail, calendar, tracking, addon buttons) to drag it to a custom position. While dragging, buttons snap to nearby buttons and the minimap border; hold Ctrl together with Shift to disable snapping."] = "Cuando está activado, Mayús+clic en cualquier botón del minimapa (correo, calendario, seguimiento, botones de addon) para arrastrarlo a una posición personalizada. Al arrastrar, los botones se ajustan a botones cercanos y al borde del minimapa; mantén pulsado Ctrl junto con Mayús para desactivar el ajuste."
L["When enabled, Shift+Click any sidebar icon to drag it to a custom position."] = "Cuando está activado, Mayús+clic en cualquier icono de la barra lateral para arrastrarlo a una posición personalizada."
L["When enabled, debuff icons keep Blizzard's colored border instead of using the custom border."] = "Cuando está activado, los iconos de perjuicio mantienen el borde coloreado de Blizzard en lugar de usar el borde personalizado."
L["When enabled, left-click dragging a window will save its position without needing to hold Shift. Ctrl+drag still does a temporary move."] = "Cuando está activado, arrastrar una ventana con clic izquierdo guardará su posición sin necesidad de mantener pulsado Mayús. Ctrl+arrastrar sigue haciendo un movimiento temporal."
L["When enabled, left-click dragging the bag window will move it without needing to hold Shift."] = "Cuando está activado, arrastrar la ventana de bolsa con clic izquierdo la moverá sin necesidad de mantener pulsado Mayús."
L["When enabled, nameplates stack vertically instead of overlapping."] = "Cuando está activado, las placas de nombre se apilan verticalmente en lugar de superponerse."
L["When enabled, the extra buttons (Great Vault, M+ Portals, Friends Online, Group Button) and any ungrouped minimap buttons only show while the mouse is over the minimap. The M+ Portals flyout keeps them shown until it closes."] = "Cuando está activado, los botones adicionales (Gran bóveda, Portales de M+, Amigos conectados, Botón de grupo) y cualquier botón de minimapa sin agrupar solo se muestran mientras el ratón está sobre el minimapa. El menú desplegable de Portales de M+ los mantiene visibles hasta que se cierra."
L["When hovering any action bar set to Mouseover, all Mouseover bars will appear."] = "Al pasar el ratón sobre cualquier barra de acción establecida en Al pasar el ratón, aparecerán todas las barras de Al pasar el ratón."
L["When on, augment rune/flask/food/weapon reminders still show (dimmed) when you have no matching item in your bags, as a prompt to restock.\nWhen off, they are hidden entirely if you don't carry the item."] = "Cuando está activado, los recordatorios de runa de aumento/frasco/comida/arma siguen mostrándose (atenuados) cuando no tienes un objeto coincidente en las bolsas, como aviso para reponer existencias.\nCuando está desactivado, se ocultan por completo si no llevas el objeto."
L["When on, flask/food/weapon reminders still show (dimmed) when you have no matching item in your bags, as a prompt to restock.\nWhen off, they are hidden entirely if you don't carry the item."] = "Cuando está activado, los recordatorios de frasco/comida/arma siguen mostrándose (atenuados) cuando no tienes un objeto coincidente en las bolsas, como aviso para reponer existencias.\nCuando está desactivado, se ocultan por completo si no llevas el objeto."
L["When the class resource bar is not shown, this automatically adds the class resource height to the power bar."] = "Cuando la barra de recurso de clase no se muestra, esto añade automáticamente la altura del recurso de clase a la barra de poder."
L["When the current spec has no bars in this group, keeps elements anchored to the group in place and shifts them up or down by one bar height (tune with the cog's Extra Y Offset) to cover its empty slot."] = "Cuando la especialización actual no tiene barras en este grupo, mantiene los elementos anclados al grupo en su lugar y los desplaza hacia arriba o abajo una altura de barra (ajusta con el Desplazamiento Y adicional del engranaje) para cubrir su ranura vacía."
L["When using custom raid sizes, don't count members in hidden groups toward the raid-size breakpoint. For example, if you hide groups 7 and 8, a full 40-man raid is sized as if it were 24-man instead of jumping to the 30-man frame size. Has no effect unless you have custom raid sizes set up."] = "Al usar tamaños de banda personalizados, no cuentes a los miembros de grupos ocultos para el punto de corte del tamaño de banda. Por ejemplo, si ocultas los grupos 7 y 8, una banda completa de 40 se dimensiona como si fuera de 24 en lugar de saltar al tamaño de marco de 30. No tiene efecto a menos que tengas configurados tamaños de banda personalizados."
L["When you are solo, center the player frame on the party frame instead of anchoring it at the top."] = "Cuando estás en solitario, centra el marco de jugador en el marco de grupo en lugar de anclarlo arriba."
L["When you join a Group Finder group for a dungeon that has a teleport, shows a small movable popup with the dungeon name and a one-click teleport button. It hides when you enter the dungeon, leave the group, or enter combat."] = "Cuando te unes a un grupo del Buscador de grupo para una mazmorra que tiene teletransporte, muestra una pequeña ventana emergente movible con el nombre de la mazmorra y un botón de teletransporte de un clic. Se oculta cuando entras en la mazmorra, sales del grupo o entras en combate."
L["When you press Escape or Space during a cinematic, the confirmation prompt is automatically accepted."] = "Cuando pulsas Escape o Espacio durante una cinemática, el aviso de confirmación se acepta automáticamente."
L["When you press an ability's keybind, show the action button's \"pushed down\" look on its icon on this bar -- even while the ability is on cooldown."] = "Cuando pulsas el atajo de teclado de una habilidad, muestra el aspecto \"presionado\" del botón de acción en su icono en esta barra -- incluso mientras la habilidad está en tiempo de reutilización."
L["When your bags have none of one combat potion type, its icon swaps to track the next type you own."] = "Cuando tus bolsas no tienen ninguna de un tipo de poción de combate, su icono cambia para seguir el siguiente tipo que posees."
L["When your bags have none of one potion type, its icon swaps to track the other type."] = "Cuando tus bolsas no tienen ninguna de un tipo de poción, su icono cambia para seguir el otro tipo."
L["When your interrupt is on cooldown now but will be ready before the enemy cast finishes, color the part of the cast bar during which your interrupt will be available. The color clears the instant your interrupt comes off cooldown."] = "Cuando tu interrupción está ahora en tiempo de reutilización pero estará lista antes de que termine el lanzamiento del enemigo, colorea la parte de la barra de lanzamiento durante la cual tu interrupción estará disponible. El color se borra en el instante en que tu interrupción sale del tiempo de reutilización."
L["When your spec has no class resource, automatically adds the class resource height to the power bar. Automatically disabled when Power Bar height is matched to another element."] = "Cuando tu especialización no tiene recurso de clase, añade automáticamente la altura del recurso de clase a la barra de poder. Se desactiva automáticamente cuando la altura de la Barra de poder se iguala a otro elemento."
L["Whenever not airborne on a skyriding mount."] = "Siempre que no estés en el aire con una montura de vuelo aéreo."
L["Where the block's content sits inside its slot."] = "Dónde se sitúa el contenido del bloque dentro de su ranura."
L["Where the icon strip sits inside its slot."] = "Dónde se sitúa la tira de iconos dentro de su ranura."
L["Where to Show"] = "Dónde mostrar"
L["Which audio channel the block's volume bar adjusts."] = "Qué canal de audio ajusta la barra de volumen del bloque."
L["Which direction new icons extend from the frame's edge."] = "En qué dirección se extienden los iconos nuevos desde el borde del marco."
L["Which end of the crest ladder comes first."] = "Qué extremo de la escala de crestas va primero."
L["Which enemy buffs show on nameplates. Important shows the buffs Blizzard flags for enemy nameplates plus anything dispellable; Dispellable shows only buffs that can be dispelled, purged or soothed. With a Dispel Glow style set, every dispellable buff shown glows."] = "Qué beneficios enemigos se muestran en las placas de nombre. Importante muestra los beneficios que Blizzard marca para placas de nombre enemigas más cualquiera disipable; Disipable muestra solo los beneficios que se pueden disipar, purgar o calmar. Con un estilo de Resplandor de disipación definido, todo beneficio disipable mostrado resplandece."
L["Which enemy buffs show on nameplates. Important shows the buffs Blizzard flags for enemy nameplates plus anything dispellable; Only Dispellable shows just the buffs that can be dispelled, purged or soothed. With a Dispel Glow style set, every dispellable buff shown glows."] = "Qué beneficios enemigos se muestran en las placas de nombre. Importante muestra los beneficios que Blizzard marca para placas de nombre enemigas más cualquiera disipable; Solo disipable muestra solo los beneficios que se pueden disipar, purgar o calmar. Con un estilo de Resplandor de disipación definido, todo beneficio disipable mostrado resplandece."
L["Which hearthstone the left click uses. Random Hearthstone picks a random owned variant each cast. Right click always rolls a random one."] = "Qué piedra de hogar usa el clic izquierdo. Piedra de hogar aleatoria elige una variante poseída al azar en cada lanzamiento. El clic derecho siempre sortea una al azar."
L["Which latency to show: home, world, or both side by side."] = "Qué latencia mostrar: local, mundial, o ambas una junto a la otra."
L["Which layer the windows and the collapsed icon draw on, relative to other frames on screen."] = "En qué capa se dibujan las ventanas y el icono contraído, en relación con otros marcos en pantalla."
L["Which micro menu buttons this block shows."] = "Qué botones de micromenú muestra este bloque."
L["Which minimap corner the Blizzard element row (tracking, calendar, mail, crafting) builds out from and the direction it grows."] = "Desde qué esquina del minimapa se construye la fila de elementos de Blizzard (seguimiento, calendario, correo, fabricación) y en qué dirección crece."
L["Which minimap corner the button row builds out from and the direction it grows."] = "Desde qué esquina del minimapa se construye la fila de botones y en qué dirección crece."
L["Which of the season's crests this block shows."] = "Cuál de las crestas de la temporada muestra este bloque."
L["Which sections the gold tooltip shows."] = "Qué secciones muestra el tooltip de oro."
L["Which view bags (and the bank) open to by default. The bank has no MultiBag view, so MultiBag opens the bank to OneBank."] = "A qué vista se abren las bolsas (y el banco) de forma predeterminada. El banco no tiene vista Multibolsa, así que Multibolsa abre el banco en Banco único."
L["Which way new bars stack as more enemies start casting."] = "En qué dirección se apilan las barras nuevas a medida que más enemigos empiezan a lanzar."
L["Which way spell flyouts (e.g. Wild Mushroom, Tiger's Fury) open from this bar. Automatic opens away from the nearest screen edge."] = "En qué dirección se abren los menús desplegables de hechizo (p. ej. Hongo salvaje, Furia del tigre) desde esta barra. Automático se abre alejándose del borde de pantalla más cercano."
L["Which way the rows stack as healers are added."] = "En qué dirección se apilan las filas a medida que se añaden sanadores."
L["Which way the windows extend from the collapsed icon when they open. The close button always lands at that same corner."] = "En qué dirección se extienden las ventanas desde el icono contraído cuando se abren. El botón de cerrar siempre acaba en esa misma esquina."
L["While dragging a spell or item, this bar appears so you can drop onto it."] = "Mientras arrastras un hechizo u objeto, esta barra aparece para que puedas soltarlo sobre ella."
L["While either grouping toggle is on, drop the trailing block of empty slots so the view only shows items. Turn this off to keep the free slots visible for depositing."] = "Mientras cualquiera de los interruptores de agrupación esté activado, se elimina el bloque final de ranuras vacías para que la vista solo muestre objetos. Desactiva esto para mantener visibles las ranuras libres para depositar."
L["While on a glide-capable mount, ground included, where Blizzard shows its vigor HUD. Skyriding (Airborne) additionally requires you to be flying."] = "Mientras estás en una montura capaz de planear, incluyendo en el suelo, donde Blizzard muestra su HUD de vigor. Vuelo aéreo (en el aire) además requiere que estés volando."
L["While resting, in a city or at an inn."] = "Mientras descansas, en una ciudad o en una posada."
L["While seated in a vehicle."] = "Mientras estás sentado en un vehículo."
L["While the spellbook or macro panel is open, this bar appears so you can drag abilities onto it."] = "Mientras el libro de hechizos o el panel de macros está abierto, esta barra aparece para que puedas arrastrar habilidades sobre ella."
L["While you are inside a house or plot."] = "Mientras estás dentro de una casa o parcela."
