L["With Hide Active State on, a charge cooldown's recharge swipe and edge now stay visible instead of disappearing while a charge is in hand or when you press another ability."] = "Con Ocultar estado activo activado, el barrido y el borde de recarga de un tiempo de reutilización de carga ahora permanecen visibles en lugar de desaparecer mientras hay una carga disponible o cuando pulsas otra habilidad."
L["With health decimals on, full health renders 100% instead of 100.0% while real decimals like 99.5% stay"] = "Con los decimales de vida activados, la vida completa se muestra como 100% en lugar de 100.0%, mientras que los decimales reales como 99.5% se mantienen"
L["With the Rectangular shape, player and party arrows no longer draw in the hidden bands above and below the map, and combat transitions no longer leave the map cut off wrong."] = "Con la forma Rectangular, las flechas de jugador y grupo ya no se dibujan en las bandas ocultas por encima y por debajo del mapa, y las transiciones de combate ya no dejan el mapa cortado incorrectamente."
