L["Works in and out of combat, unlike Auto-Repair. When a group-wide raid buff's column header shows it's missing on someone, the icon blinks and sends the buff's spell link. In a raid, left-click reaches a provider in groups 1-4 and right-click one in groups 5-8; outside a raid, left-click reaches the only provider found. Hovering the icon always shows who each click would whisper, or that everyone already has it."] = "Funciona dentro y fuera de combate, a diferencia de Auto-reparación. Cuando el encabezado de columna de un beneficio de banda grupal muestra que le falta a alguien, el icono parpadea y envía el enlace de hechizo del beneficio. En una banda, el clic izquierdo contacta con un proveedor de los grupos 1-4 y el clic derecho con uno de los grupos 5-8; fuera de una banda, el clic izquierdo contacta con el único proveedor encontrado. Pasar el ratón sobre el icono siempre muestra a quién susurraría cada clic, o que todos ya lo tienen."
